def _make_int_check(lo: int, hi: int | None) -> object:
    def check(value: object) -> bool:
        if isinstance(value, bool):
            return False
        return isinstance(value, int) and value >= lo and (hi is None or value <= hi)
    return check


_VALIDATORS: dict[str, object] = {
    "port": _make_int_check(1, 65535),
    "workers": _make_int_check(1, None),
    "host": lambda v: isinstance(v, str) and v,
    "debug": lambda v: isinstance(v, bool),
}


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    config: dict[str, object] = dict(DEFAULTS)

    for key in _VALIDATORS:
        if key in raw and not _VALIDATORS[key](raw[key]):
            return dict(DEFAULTS)
        if key in raw:
            config[key] = raw[key]

    return config

