from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad grid: width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad grid: height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad grid: cell_size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill_value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[tuple[int, int], int] = defaultdict(int)
    counts: dict[tuple[int, int], int] = defaultdict(int)
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation: not a dict"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation: x"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation: y"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation: value"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation: quality"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation: quality out of range"}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        x = obs["x"]
        if x < 0:
            dropped += 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue

        y = obs["y"]
        if y < 0:
            dropped += 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] += obs["value"]
        counts[key] += 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: set[tuple[int, int]],
    width: int,
    height: int,
) -> list[list[str]]:
    return [
        ["empty" if (row, col) not in counts
         else "degraded" if (row, col) in degraded
         else "good"
         for col in range(width)]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    total = width * height
    return len(counts) * 100 // total if total else 0


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return f"cells={total_cells};filled={filled};dropped={dropped};rejected={rejected};saturated={saturated};coverage={coverage}"

from __future__ import annotations

from typing import Sequence

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    error = validate_input(raw)
    if error:
        return {"ok": False, "error": error}

    width = raw["grid"]["width"]
    height = raw["grid"]["height"]
    cell_size = raw["grid"]["cell_size"]
    fill_value = raw["fill_value"]
    observations = raw["observations"]

    grid = _init_grid(width, height)
    counts = [[0] * width for _ in range(height)]
    saturated_flags = [[False] * width for _ in range(height)]
    degraded_flags = [[False] * width for _ in range(height)]

    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        result = _process_observation(obs, width, height, cell_size, tolerance, counts)
        if result["error"]:
            return {"ok": False, "error": result["error"]}
        if result["skip"]:
            dropped += 1
            continue
        if result["rejected"]:
            rejected += 1
            continue
        if result["saturated"]:
            saturated_flags[result["row"]][result["col"]] = True
            saturated += 1
            continue
        grid[result["row"]][result["col"]] += result["value"]
        counts[result["row"]][result["col"]] += 1
        if result["quality"] < GOOD_QUALITY:
            degraded_flags[result["row"]][result["col"]] = True

    cells = _averaged_rows(grid, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded_flags, width, height, saturated_flags)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, _filled_cells(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return "missing field"
    error = validate_grid(raw["grid"])
    if error:
        return error
    if _bad_int(raw["fill_value"]):
        return "bad fill value"
    if not isinstance(raw["observations"], list):
        return "bad observations"
    return None


def validate_grid(grid: object) -> str | None:
    if not isinstance(grid, dict):
        return "bad grid"
    required = ("width", "height", "cell_size")
    if any(key not in grid for key in required):
        return "bad grid"
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if _bad_int(width) or width < 1 or width > MAX_DIM:
        return "bad width"
    if _bad_int(height) or height < 1 or height > MAX_DIM:
        return "bad height"
    if _bad_int(cell_size) or cell_size < 1:
        return "bad cell size"
    return None


def _init_grid(width: int, height: int) -> list[list[int]]:
    return [[0] * width for _ in range(height)]


def _bad_int(v: object) -> bool:
    return not isinstance(v, int) or isinstance(v, bool)


def _is_int(v: object) -> bool:
    return isinstance(v, int) and not isinstance(v, bool)


def _process_observation(
    obs: object, width: int, height: int, cell_size: int, tolerance: int, counts: list[list[int]]
) -> dict:
    if not isinstance(obs, dict):
        return {"error": "bad observation"}

    x = obs.get("x")
    y = obs.get("y")
    value = obs.get("value")
    quality = obs.get("quality")

    if not _is_int(x) or not _is_int(y) or not _is_int(value) or not _is_int(quality):
        return {"error": "bad observation"}
    if quality < 0 or quality > 100:
        return {"error": "bad observation"}
    if quality < MIN_QUALITY:
        return {"rejected": True}

    row, col, ok = _map_to_cell(x, y, cell_size, width, height, tolerance)
    if not ok:
        return {"skip": True}
    if counts[row][col] >= SATURATION_LIMIT:
        return {"saturated": True}
    return {"row": row, "col": col, "value": value, "quality": quality}


def _map_to_cell(
    x: int, y: int, cell_size: int, width: int, height: int, tolerance: int
) -> tuple[int, int, bool]:
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return (-1, -1, False)

    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return (-1, -1, False)

    return (row, col, True)


def _averaged_rows(sums: list[list[int]], counts: list[list[int]], width: int, height: int, fill_value: int) -> list[list[int]]:
    return [
        [
            sums[row][col] // counts[row][col] if counts[row][col] else fill_value
            for col in range(width)
        ]
        for row in range(height)
    ]


def _flag_rows(
    counts: list[list[int]],
    degraded: list[list[bool]],
    width: int,
    height: int,
    saturated_flags: list[list[bool]],
) -> list[list[str]]:
    return [
        [
            "empty"
            if not counts[row][col]
            else "degraded" if degraded[row][col] else "good"
            for col in range(width)
        ]
        for row in range(height)
    ]


def _coverage(counts: list[list[int]], width: int, height: int) -> int:
    return _filled_cells(counts) * 100 // (width * height)


def _filled_cells(counts: list[list[int]]) -> int:
    return sum(1 for row in counts for c in row if c > 0)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells};filled={filled};dropped={dropped};"
        f"rejected={rejected};saturated={saturated};coverage={coverage}"
    )

from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    grid_params, err = _validate_input(raw)
    if err:
        return {"ok": False, "error": err}
    sums, counts, degraded, dropped, rejected, saturated = _process_observations(
        raw["observations"], grid_params
    )
    cells = _averaged_rows(sums, counts, grid_params.width, grid_params.height, grid_params.fill_value)
    flags = _flag_rows(counts, degraded, grid_params.width, grid_params.height)
    coverage = _coverage(counts, grid_params.width, grid_params.height)
    line = _summary_line(
        grid_params.width * grid_params.height,
        len(counts),
        dropped,
        rejected,
        saturated,
        coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


class _GridParams:
    __slots__ = ("width", "height", "cell_size", "fill_value")

    def __init__(self, width: int, height: int, cell_size: int, fill_value: int) -> None:
        self.width = width
        self.height = height
        self.cell_size = cell_size
        self.fill_value = fill_value


def _validate_input(raw: object) -> tuple[_GridParams | None, str | None]:
    if not isinstance(raw, dict):
        return (None, "malformed input")
    for key in ("grid", "observations", "fill_value"):
        if key not in raw:
            return (None, "missing field")
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return (None, "bad grid")
    grid_err = _validate_grid(grid)
    if grid_err:
        return (None, grid_err)
    if not isinstance(raw["fill_value"], int):
        return (None, "bad fill value")
    if not isinstance(raw["observations"], list):
        return (None, "bad observations")
    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    return (
        _GridParams(width, height, cell_size, raw["fill_value"]),
        None,
    )


def _validate_grid(grid: object) -> str | None:
    if not isinstance(grid, dict):
        return "bad grid"
    for key in ("width", "height", "cell_size"):
        if key not in grid:
            return "bad grid"
    err = _validate_int(grid["width"], 1, MAX_DIM, "width")
    if err:
        return err
    err = _validate_int(grid["height"], 1, MAX_DIM, "height")
    if err:
        return err
    return _validate_int(grid["cell_size"], 1, None, "cell size")


def _validate_int(value: object, lo: int, hi: int | None, name: str) -> str | None:
    if not isinstance(value, int):
        return f"bad {name}"
    if value < lo or (hi is not None and value > hi):
        return f"bad {name}"
    return None


class _GridCoord:
    __slots__ = ("ok", "row", "col")

    def __init__(self, ok: bool, row: int = 0, col: int = 0) -> None:
        self.ok = ok
        self.row = row
        self.col = col


def _resolve_coord(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int
) -> _GridCoord:
    x = obs["x"]
    if x < 0:
        return _GridCoord(False)
    col, ok = _wrap_index(x, width, cell_size, tolerance)
    if not ok:
        return _GridCoord(False)

    y = obs["y"]
    if y < 0:
        return _GridCoord(False)
    row, ok = _wrap_index(y, height, cell_size, tolerance)
    if not ok:
        return _GridCoord(False)

    return _GridCoord(True, row, col)


def _process_observations(
    observations: list,
    grid_params: _GridParams,
) -> tuple[defaultdict, defaultdict, dict, int, int, int]:
    sums: dict[tuple[int, int], int] = defaultdict(int)
    counts: dict[tuple[int, int], int] = defaultdict(int)
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = grid_params.cell_size // 2
    for obs in observations:
        if not _validate_observation(obs):
            return (sums, counts, degraded, 0, 0, 0)

        quality = obs["quality"]
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        coord = _resolve_coord(obs, grid_params.width, grid_params.height, grid_params.cell_size, tolerance)
        if not coord.ok:
            dropped += 1
            continue

        key = (coord.row, coord.col)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] += obs["value"]
        counts[key] += 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    return (sums, counts, degraded, dropped, rejected, saturated)


def _validate_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for key in ("x", "y", "value", "quality"):
        if key not in obs or not isinstance(obs[key], int):
            return False
    quality = obs["quality"]
    return 0 <= quality <= 100


def _wrap_index(coord: int, limit: int, cell_size: int, tolerance: int) -> tuple[int, bool]:
    idx = coord // cell_size
    if idx >= limit:
        if coord - limit * cell_size < tolerance:
            return (limit - 1, True)
        return (-1, False)
    return (idx, True)


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
