from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not _is_valid_observation(obs):
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col = _bucket(obs["x"], cell_size, width, tolerance)
        if col is None:
            dropped += 1
            continue

        row = _bucket(obs["y"], cell_size, height, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    def cell(row: int, col: int) -> int:
        key = (row, col)
        return sums[key] // counts[key] if key in counts else fill_value

    return [[cell(row, col) for col in range(width)] for row in range(height)]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    def flag(row: int, col: int) -> str:
        key = (row, col)
        if key not in counts:
            return "empty"
        return "degraded" if key in degraded else "good"

    return [[flag(row, col) for col in range(width)] for row in range(height)]


def _bucket(value: int, cell_size: int, extent: int, tolerance: int) -> int | None:
    if value < 0:
        return None
    idx = value // cell_size
    if idx < extent:
        return idx
    if value - extent * cell_size < tolerance:
        return extent - 1
    return None


def _is_valid_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return False
    q = obs["quality"]
    return 0 <= q <= 100


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (f"cells={total_cells};filled={filled};dropped={dropped}"
            f";rejected={rejected};saturated={saturated};coverage={coverage}")

from __future__ import annotations

from typing import Any, NamedTuple


MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def _is_valid_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_input(raw: dict) -> tuple[int, int, int, int, list[dict]] | str:
    if not isinstance(raw.get("grid"), dict):
        return "bad grid"
    grid = raw["grid"]
    if not all(k in grid and _is_valid_int(grid[k]) for k in ("width", "height", "cell_size")):
        return "bad grid"
    width, height, cell_size = int(grid["width"]), int(grid["height"]), int(grid["cell_size"])
    if not (1 <= width <= MAX_DIM and 1 <= height <= MAX_DIM and cell_size >= 1):
        return "bad grid"
    if not _is_valid_int(raw.get("fill_value")):
        return "bad fill value"
    if not isinstance(raw.get("observations"), list):
        return "bad observations"
    return width, height, cell_size, int(raw["fill_value"]), raw["observations"]


def _validate_obs(obs: dict) -> tuple[int, int, int, int] | str:
    if not isinstance(obs, dict):
        return "bad observation"
    if not all(k in obs and _is_valid_int(obs[k]) for k in ("x", "y", "value", "quality")):
        return "bad observation"
    quality = obs["quality"]
    if not (0 <= quality <= 100):
        return "bad observation"
    return obs["x"], obs["y"], obs["value"], quality


class _ClipResult(NamedTuple):
    col: int
    row: int
    in_grid: bool


def _clip_to_grid(
    x: int, y: int, width: int, height: int, cell_size: int, tolerance: int,
) -> _ClipResult:
    col = x // cell_size
    row = y // cell_size
    clipped = False
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
            clipped = True
        else:
            return _ClipResult(col, row, False)
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
            clipped = True
        else:
            return _ClipResult(col, row, False)
    return _ClipResult(col, row, clipped)


class _ObsAction(NamedTuple):
    kind: str
    row: int = 0
    col: int = 0


def _dispatch_obs(
    x: int, y: int, quality: int,
    width: int, height: int, cell_size: int, tolerance: int,
) -> _ObsAction:
    if quality < MIN_QUALITY:
        return _ObsAction("reject")
    if x < 0 or y < 0:
        return _ObsAction("drop")
    cr = _clip_to_grid(x, y, width, height, cell_size, tolerance)
    if not cr.in_grid:
        return _ObsAction("drop")
    return _ObsAction("accept", cr.row, cr.col)


def _accumulate(
    observations: list[dict[str, Any]],
    width: int,
    height: int,
    cell_size: int,
    fill_value: int,
) -> tuple[
    dict[tuple[int, int], int],
    dict[tuple[int, int], int],
    dict[tuple[int, int], bool],
    int, int, int,
]:
    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = rejected = saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        result = _validate_obs(obs)
        if isinstance(result, str):
            return sums, counts, degraded, dropped, rejected, saturated
        x, y, value, quality = result
        action = _dispatch_obs(x, y, quality, width, height, cell_size, tolerance)
        if action.kind == "reject":
            rejected += 1
            continue
        if action.kind == "drop":
            dropped += 1
            continue
        key = (action.row, action.col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + value
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    return sums, counts, degraded, dropped, rejected, saturated


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    result = _validate_input(raw)
    if isinstance(result, str):
        return {"ok": False, "error": result}
    width, height, cell_size, fill_value, observations = result

    sums, counts, degraded, dropped, rejected, saturated = _accumulate(
        observations, width, height, cell_size, fill_value,
    )

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list[list[str]]:
    return [
        [
            "empty" if (row, col) not in counts
            else "degraded" if (row, col) in degraded
            else "good"
            for col in range(width)
        ]
        for row in range(height)
    ]


def _coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height) if width * height else 0


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    parts = (
        f"cells={total_cells}",
        f"filled={filled}",
        f"dropped={dropped}",
        f"rejected={rejected}",
        f"saturated={saturated}",
        f"coverage={coverage}",
    )
    return ";".join(parts)

from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def _validate_input(raw: object) -> dict | None:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    for field in ("grid", "observations", "fill_value"):
        if field not in raw:
            return {"ok": False, "error": "missing field"}
    if not isinstance(raw["grid"], dict):
        return {"ok": False, "error": "bad grid"}
    for field in ("width", "height", "cell_size"):
        if field not in raw["grid"]:
            return {"ok": False, "error": "bad grid"}
    return None


def _validate_params(raw: dict) -> dict | None:
    checks: list[tuple[str, object, str | tuple[int, int]]] = [
        ("bad width", raw["grid"]["width"], ("range", (1, MAX_DIM))),
        ("bad height", raw["grid"]["height"], ("range", (1, MAX_DIM))),
        ("bad cell size", raw["grid"]["cell_size"], ("min", 1)),
        ("bad fill value", raw["fill_value"], "int"),
        ("bad observations", raw["observations"], "list"),
    ]
    for label, value, constraint in checks:
        if err := _check_constraint(label, value, constraint):
            return err
    return None


def _check_constraint(label: str, value: object, constraint: str | tuple[int, int]) -> dict | None:
    match constraint:
        case "int":
            return _check_int(label, value)
        case "list":
            return _check_list(label, value)
        case ("range", (lo, hi)):
            return _check_range(label, value, lo, hi)
        case ("min", min_val):
            return _check_min(label, value, min_val)


def _check_int(label: str, value: object) -> dict | None:
    if not isinstance(value, int):
        return {"ok": False, "error": label}
    return None


def _check_list(label: str, value: object) -> dict | None:
    if not isinstance(value, list):
        return {"ok": False, "error": label}
    return None


def _check_range(label: str, value: object, lo: int, hi: int) -> dict | None:
    if not isinstance(value, int) or not (lo <= value <= hi):
        return {"ok": False, "error": label}
    return None


def _check_min(label: str, value: object, min_val: int) -> dict | None:
    if not isinstance(value, int) or value < min_val:
        return {"ok": False, "error": label}
    return None


def accumulate_grid(raw: object) -> dict:
    if err := _validate_input(raw):
        return err
    if err := _validate_params(raw):
        return err

    grid = raw["grid"]
    width, height, cell_size = grid["width"], grid["height"], grid["cell_size"]
    tolerance = cell_size // 2

    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = rejected = saturated = 0

    for obs in raw["observations"]:
        if err := _validate_obs(obs):
            return err
        if _reject_low_quality(obs, MIN_QUALITY):
            rejected += 1
            continue

        coord = _map_coords(obs["x"], obs["y"], width, height, cell_size, tolerance)
        if coord is None:
            dropped += 1
            continue

        key = coord
        if _skip_if_saturated(key, counts, SATURATION_LIMIT):
            saturated += 1
            continue

        _accumulate(obs, key, sums, counts, degraded, GOOD_QUALITY)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(
        width * height, len(counts), dropped, rejected, saturated, coverage
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_obs(obs: object) -> dict | None:
    if not isinstance(obs, dict):
        return {"ok": False, "error": "bad observation"}
    for field in ("x", "y", "value", "quality"):
        if field not in obs or not isinstance(obs[field], int):
            return {"ok": False, "error": "bad observation"}
    if not (0 <= obs["quality"] <= 100):
        return {"ok": False, "error": "bad observation"}
    return None


def _reject_low_quality(obs: dict, threshold: int) -> bool:
    return obs["quality"] < threshold


def _map_coords(x: int, y: int, width: int, height: int, cell_size: int, tolerance: int) -> tuple[int, int] | None:
    if x < 0 or y < 0:
        return None
    col = x // cell_size
    if col >= width and x - width * cell_size >= tolerance:
        return None
    if col >= width:
        col = width - 1

    row = y // cell_size
    if row >= height and y - height * cell_size >= tolerance:
        return None
    if row >= height:
        row = height - 1

    return row, col


def _skip_if_saturated(key: tuple[int, int], counts: dict, limit: int) -> bool:
    return counts.get(key, 0) >= limit


def _accumulate(obs: dict, key: tuple[int, int], sums: dict, counts: dict, degraded: dict, good_quality: int) -> None:
    sums[key] = sums.get(key, 0) + obs["value"]
    counts[key] = counts.get(key, 0) + 1
    if obs["quality"] < good_quality:
        degraded[key] = True


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
