        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list[list[str]]:
    return [
        [
            "empty" if (row, col) not in counts else "degraded" if (row, col) in degraded else "good"
            for col in range(width)
        ]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
