from __future__ import annotations

from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    config = _validate_config(raw)
    if config is None:
        return {"ok": False, "error": "bad grid"}

    return _accumulate(config, raw["observations"])


def _accumulate(
    config: tuple[int, int, int, int],
    observations: list,
) -> dict:
    width, height, cell_size, fill_value = config

    sums: dict[tuple[int, int], int] = defaultdict(int)
    counts: dict[tuple[int, int], int] = defaultdict(int)
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _validate_observation(obs):
            return {"ok": False, "error": "bad observation"}

        quality = obs["quality"]
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        col, dropped_x = _bucket(obs["x"], cell_size, width, tolerance)
        if dropped_x:
            dropped += 1
            continue

        row, dropped_y = _bucket(obs["y"], cell_size, height, tolerance)
        if dropped_y:
            dropped += 1
            continue

        key = (row, col)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue

        sums[key] += obs["value"]
        counts[key] += 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(
        width * height, len(counts), dropped, rejected, saturated, coverage
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    x, y, value, quality = obs.get("x"), obs.get("y"), obs.get("value"), obs.get("quality")
    return (
        isinstance(x, int)
        and isinstance(y, int)
        and isinstance(value, int)
        and isinstance(quality, int)
        and 0 <= quality <= 100
    )


def _validate_raw_structure(raw: object) -> tuple | None:
    if not isinstance(raw, dict):
        return None

    grid = raw.get("grid")
    observations = raw.get("observations")
    fill_value = raw.get("fill_value")

    if grid is None or observations is None or fill_value is None:
        return None
    if not isinstance(observations, list) or not isinstance(fill_value, int):
        return None
    if not isinstance(grid, dict):
        return None

    return grid, observations, fill_value


def _extract_grid_dims(grid: dict) -> tuple[int | None, int | None, int | None]:
    return grid.get("width"), grid.get("height"), grid.get("cell_size")


def _validate_grid_dims(width: int | None, height: int | None, cell_size: int | None) -> tuple[int, int, int] | None:
    if width is None or height is None or cell_size is None:
        return None

    valid_size = lambda v: isinstance(v, int) and 1 <= v <= MAX_DIM
    if not valid_size(width) or not valid_size(height) or not (isinstance(cell_size, int) and cell_size >= 1):
        return None

    return width, height, cell_size


def _validate_grid(grid: dict) -> tuple[int, int, int] | None:
    width, height, cell_size = _extract_grid_dims(grid)
    return _validate_grid_dims(width, height, cell_size)


def _validate_config(raw: object) -> tuple[int, int, int, int] | None:
    raw_structure = _validate_raw_structure(raw)
    if raw_structure is None:
        return None
    grid, observations, fill_value = raw_structure
    grid_dims = _validate_grid(grid)
    if grid_dims is None:
        return None
    width, height, cell_size = grid_dims
    return width, height, cell_size, fill_value


def _bucket(position: int, cell_size: int, limit: int, tolerance: int) -> tuple[int, bool]:
    if position < 0:
        return (0, True)

    col = position // cell_size
    if col >= limit:
        if position - limit * cell_size < tolerance:
            return (limit - 1, False)
        return (0, True)

    return (col, False)


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(r, c)] // counts[(r, c)] if (r, c) in counts else fill_value for c in range(width)]
        for r in range(height)
    ]


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    return [
        [
            "empty" if (r, c) not in counts
            else "degraded" if (r, c) in degraded
            else "good"
            for c in range(width)
        ]
        for r in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        f"cells={total_cells}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )

