    if not _REQUIRED_KEYS.issubset(raw):
        return dict(DEFAULT)
    if not all(_FIELD_VALIDATORS[key](raw[key]) for key in _REQUIRED_KEYS):
        return dict(DEFAULT)

    return {key: raw[key] for key in _REQUIRED_KEYS} | {"valid": True}

