from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def _validate_structure(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}

    grid = raw.get("grid")
    observations = raw.get("observations")
    fill_value = raw.get("fill_value")
    if grid is None or observations is None or fill_value is None:
        return {"ok": False, "error": "missing field"}
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    if not isinstance(fill_value, int):
        return {"ok": False, "error": "bad fill value"}

    return {"ok": True, "grid": grid, "observations": observations, "fill_value": fill_value}


def _validate_width(grid: dict) -> dict:
    value = grid.get("width")
    if value is None:
        return {"ok": False, "error": "bad grid"}
    if not isinstance(value, int) or value < 1 or value > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    return {"ok": True, "width": value}


def _validate_height(grid: dict) -> dict:
    value = grid.get("height")
    if value is None:
        return {"ok": False, "error": "bad grid"}
    if not isinstance(value, int) or value < 1 or value > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    return {"ok": True, "height": value}


def _validate_cell_size(grid: dict) -> dict:
    value = grid.get("cell_size")
    if value is None:
        return {"ok": False, "error": "bad grid"}
    if not isinstance(value, int) or value < 1:
        return {"ok": False, "error": "bad cell size"}
    return {"ok": True, "cell_size": value}


def _validate_observation_structure(obs: object) -> dict | None:
    if not isinstance(obs, dict):
        return None

    x = obs.get("x")
    y = obs.get("y")
    value = obs.get("value")
    quality = obs.get("quality")
    if x is None or y is None or value is None or quality is None:
        return None
    if not isinstance(x, int) or not isinstance(y, int) or not isinstance(value, int) or not isinstance(quality, int):
        return None

    return {"x": x, "y": y, "value": value, "quality": quality}


def _validate_observation_values(x: int, y: int, value: int, quality: int) -> bool:
    return 0 <= quality <= 100


def _resolve_to_cell(x: int, y: int, width: int, height: int, cell_size: int) -> tuple[int, int] | None:
    tolerance = cell_size // 2

    if x < 0 or y < 0:
        return None

    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return None

    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return None

    return (row, col)


def _classify_observation(quality: int, counts: dict, key: tuple[int, int]) -> str:
    if quality < MIN_QUALITY:
        return "rejected"
    cell_count = counts.get(key, 0)
    if cell_count >= SATURATION_LIMIT:
        return "saturated"
    return "accepted"


def _accumulate(sums: dict, counts: dict, degraded: dict, value: int, quality: int, key: tuple[int, int]) -> None:
    sums[key] = sums.get(key, 0) + value
    counts[key] = counts.get(key, 0) + 1
    if quality < GOOD_QUALITY:
        degraded[key] = True


def _process_observations(observations: list, width: int, height: int, cell_size: int) -> dict:
    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0

    for obs in observations:
        parsed = _validate_observation_structure(obs)
        if parsed is None:
            return {"error": "bad observation"}
        if not _validate_observation_values(parsed["x"], parsed["y"], parsed["value"], parsed["quality"]):
            return {"error": "bad observation"}

        cell = _resolve_to_cell(parsed["x"], parsed["y"], width, height, cell_size)
        if cell is None:
            dropped += 1
            continue

        status = _classify_observation(parsed["quality"], counts, cell)
        if status == "rejected":
            rejected += 1
            continue

        if status == "saturated":
            saturated += 1
            continue

        _accumulate(sums, counts, degraded, parsed["value"], parsed["quality"], cell)

    return {
        "sums": sums,
        "counts": counts,
        "degraded": degraded,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
    }


def _averaged_rows(sums: dict[tuple[int, int], int], counts: dict[tuple[int, int], int],
                   width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cell_counts = counts.get(key)
            if cell_counts is not None:
                cells.append(sums[key] // cell_counts)
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict[tuple[int, int], int], degraded: dict[tuple[int, int], bool],
               width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (f"cells={total_cells};filled={filled};dropped={dropped}"
            f";rejected={rejected};saturated={saturated};coverage={coverage}")


def accumulate_grid(raw: object) -> dict:
    struct = _validate_structure(raw)
    if "error" in struct:
        return struct

    width = _validate_width(struct["grid"])
    if "error" in width:
        return {"ok": False, "error": width["error"]}

    height = _validate_height(struct["grid"])
    if "error" in height:
        return {"ok": False, "error": height["error"]}

    cell_size = _validate_cell_size(struct["grid"])
    if "error" in cell_size:
        return {"ok": False, "error": cell_size["error"]}

    result = _process_observations(struct["observations"], width["width"], height["height"], cell_size["cell_size"])
    if "error" in result:
        return {"ok": False, "error": result["error"]}

    cells = _averaged_rows(result["sums"], result["counts"], width["width"], height["height"], struct["fill_value"])
    flags = _flag_rows(result["counts"], result["degraded"], width["width"], height["height"])
    coverage = _coverage(result["counts"], width["width"], height["height"])
    line = _summary_line(
        width["width"] * height["height"], len(result["counts"]),
        result["dropped"], result["rejected"], result["saturated"], coverage
    )

    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": result["dropped"],
        "rejected": result["rejected"],
        "saturated": result["saturated"],
        "coverage": coverage,
        "line": line,
    }

