from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
VALID_TIERS = frozenset(TIER_FEES)
VALID_METHODS = frozenset(("card", "transfer"))


def _validate_common(member: dict, payment: dict) -> dict | None:
    if not isinstance(member.get("id"), str) or not member["id"]:
        return {"ok": False, "error": "bad member id"}
    if member.get("tier") not in VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    if not isinstance(payment.get("amount"), int) or isinstance(payment.get("amount"), bool) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment.get("method") not in VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    return None


def _receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _ok(status: str, fee: int, receipt: str) -> dict:
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def _check_insufficient(payment_amount: int, fee: int) -> dict | None:
    if payment_amount < fee:
        return {"ok": False, "error": "insufficient payment"}
    return None


def _handle_active(member: dict, payment: dict) -> dict:
    err = _validate_common(member, payment)
    if err is not None:
        return err
    fee = TIER_FEES[member["tier"]]
    if err := _check_insufficient(payment["amount"], fee):
        return err
    return _ok("renewed", fee, _receipt(payment["method"], member["id"], "renewed", fee))


def _check_lapsed_expiry(member: dict) -> dict | None:
    if "expired_days" not in member or not isinstance(member["expired_days"], int) or isinstance(member["expired_days"], bool) or member["expired_days"] < 0:
        return {"ok": False, "error": "bad expiry"}
    return None


def _handle_lapsed(member: dict, payment: dict) -> dict:
    err = _validate_common(member, payment)
    if err is not None:
        return err
    if err := _check_lapsed_expiry(member):
        return err
    if member["expired_days"] <= GRACE_DAYS:
        fee = TIER_FEES[member["tier"]] + LATE_FEE
        new_status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        new_status = "reinstated"
    if err := _check_insufficient(payment["amount"], fee):
        return err
    return _ok(new_status, fee, _receipt(payment["method"], member["id"], new_status, fee))


def _check_suspended(member: dict) -> dict | None:
    if "strikes" not in member or not isinstance(member["strikes"], int) or isinstance(member["strikes"], bool) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    return None


def _handle_suspended(member: dict, payment: dict) -> dict:
    err = _validate_common(member, payment)
    if err is not None:
        return err
    if err := _check_suspended(member):
        return err
    tier_fee = TIER_FEES[member["tier"]]
    fee = tier_fee + tier_fee // 2
    if err := _check_insufficient(payment["amount"], fee):
        return err
    return _ok("reactivated", fee, _receipt(payment["method"], member["id"], "reactivated", fee))


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}

    member = raw_member
    payment = raw_payment

    if not all(k in member for k in ("id", "status", "tier")):
        return {"ok": False, "error": "missing member field"}
    if not all(k in payment for k in ("amount", "method")):
        return {"ok": False, "error": "missing payment field"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}
    if status == "active":
        return _handle_active(member, payment)
    if status == "lapsed":
        return _handle_lapsed(member, payment)
    if status == "suspended":
        return _handle_suspended(member, payment)

    return {"ok": False, "error": "unknown status"}

from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
VALID_TIERS = {"basic", "gold"}
TIER_FEES = {"basic": 40, "gold": 90}
VALID_METHODS = {"card", "transfer"}


def _make_receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _ok(status: str, fee: int, receipt: str) -> dict:
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def _err(msg: str) -> dict:
    return {"ok": False, "error": msg}


def _validate_common(member: dict, payment: dict) -> dict | None:
    if member["tier"] not in VALID_TIERS:
        return _err("unknown tier")
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return _err("bad amount")
    if payment["method"] not in VALID_METHODS:
        return _err("unsupported method")
    return None


def _pay(member: dict, payment: dict, fee: int, result_status: str) -> dict:
    if payment["amount"] < fee:
        return _err("insufficient payment")
    return _ok(result_status, fee, _make_receipt(payment["method"], member["id"], result_status, fee))


_STATUS_SPEC = {
    "active": lambda m: TIER_FEES[m["tier"]],
    "lapsed": lambda m: TIER_FEES[m["tier"]] + (LATE_FEE if m["expired_days"] <= GRACE_DAYS else REINSTATE_SURCHARGE),
    "suspended": lambda m: TIER_FEES[m["tier"]] + TIER_FEES[m["tier"]] // 2,
}

_STATUS_RESULT = {
    "active": "renewed",
    "lapsed": lambda m: "renewed" if m["expired_days"] <= GRACE_DAYS else "reinstated",
    "suspended": "reactivated",
}

_STATUS_EXTRA_VALID = {
    "lapsed": lambda m: "expired_days" in m and isinstance(m["expired_days"], int) and m["expired_days"] >= 0,
    "suspended": lambda m: "strikes" in m and isinstance(m["strikes"], int) and m["strikes"] >= 0,
}
_STATUS_EXTRA_ERR = {
    "lapsed": "bad expired_days",
    "suspended": lambda m: "too many strikes" if m.get("strikes", 0) >= MAX_STRIKES else "bad strikes",
}


def _route(status: str, member: dict, payment: dict) -> dict:
    if status == "banned":
        return _err("member banned")
    if status not in _STATUS_SPEC:
        return _err("unknown status")
    err = _validate_common(member, payment)
    if err is not None:
        return err
    extra_valid = _STATUS_EXTRA_VALID.get(status)
    extra_err = _STATUS_EXTRA_ERR.get(status)
    if extra_valid is not None and not extra_valid(member):
        return _err(extra_err(member) if callable(extra_err) else extra_err)
    fee = _STATUS_SPEC[status](member)
    rs = _STATUS_RESULT[status]
    result_status = rs(member) if callable(rs) else rs
    return _pay(member, payment, fee, result_status)


def _validate_fields(obj: dict, required: list[str], label: str) -> dict | None:
    for field in required:
        if field not in obj:
            return _err(label)
    return None


def _validate_input(raw_member: object, raw_payment: object) -> dict | tuple[dict, dict]:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return _err("malformed input")
    member = raw_member
    payment = raw_payment
    err = _validate_fields(member, ["id", "status", "tier"], "missing member field")
    if err is not None:
        return err
    err = _validate_fields(payment, ["amount", "method"], "missing payment field")
    if err is not None:
        return err
    if not isinstance(member["id"], str) or not member["id"]:
        return _err("bad member id")
    return member, payment


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    result = _validate_input(raw_member, raw_payment)
    if isinstance(result, dict):
        return result
    member, payment = result
    return _route(member["status"], member, payment)

from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

_MEMBER_FIELDS = ("id", "status", "tier")
_PAYMENT_FIELDS = ("amount", "method")
_VALID_STATUSES = {"active", "lapsed", "suspended"}


def _make_receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _validate_payment(amount: int, method: str) -> dict | None:
    if not isinstance(amount, int) or amount <= 0:
        return {"ok": False, "error": "bad amount"}
    if method not in ("card", "transfer"):
        return {"ok": False, "error": "unsupported method"}


def _check_expired_days(member: dict) -> str | None:
    ed = member.get("expired_days")
    if ed is None or not isinstance(ed, int) or ed < 0:
        return "bad expiry"
    return None


def _check_strikes(member: dict) -> str | None:
    s = member.get("strikes")
    if s is None or not isinstance(s, int) or s < 0:
        return "bad strikes"
    if s >= MAX_STRIKES:
        return "too many strikes"
    return None


_STATUS_EXTRA_CHECKS = {
    "lapsed": _check_expired_days,
    "suspended": _check_strikes,
}


def _compute_fee_and_status(member: dict) -> tuple[int, str]:
    tier_fee = TIER_FEES[member["tier"]]
    if member["status"] == "active":
        return tier_fee, "renewed"
    if member["status"] == "lapsed":
        if member["expired_days"] <= GRACE_DAYS:
            return tier_fee + LATE_FEE, "renewed"
        return tier_fee + REINSTATE_SURCHARGE, "reinstated"
    return tier_fee + tier_fee // 2, "reactivated"


def _process_member(member: dict, payment: dict, status: str) -> dict:
    extra = _STATUS_EXTRA_CHECKS.get(status)
    if extra:
        err = extra(member)
        if err:
            return {"ok": False, "error": err}
    if err := _validate_payment(payment["amount"], payment["method"]):
        return err
    fee, new_status = _compute_fee_and_status(member)
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    receipt = _make_receipt(payment["method"], member["id"], new_status, fee)
