def _char_type_info(pw: str) -> tuple[int, bool]:
    has_lower = any(ch.islower() for ch in pw)
    has_upper = any(ch.isupper() for ch in pw)
    has_digit = any(ch.isdigit() for ch in pw)
    has_symbol = any(not ch.isalnum() for ch in pw)
    return (
        int(has_lower) + int(has_upper) + int(has_digit) + int(has_symbol),
        has_symbol,
    )


def _length_score(pw: str) -> int:
    length = len(pw)
    if length >= 8:
        return 1
    if length < 4:
        return -1
    return 0


def _repeat_score(pw: str) -> int:
    repeats = sum(1 for i in range(1, len(pw)) if pw[i] == pw[i - 1])
    if repeats >= 3:
        return -2
    if repeats >= 1:
        return -1
    return 0


def _bonus_score(pw: str, has_symbol: bool) -> int:
    if len(pw) >= 12 and has_symbol:
        return 1
    return 0


def password_strength(pw: str) -> int:
    score, has_symbol = _char_type_info(pw)
    score += _length_score(pw)
    score += _repeat_score(pw)
    score += _bonus_score(pw, has_symbol)
    return max(score, 0)

