def _preprocess(member: dict, payment: dict) -> dict:
    for field in ("id", "status", "tier"):
        if field not in member:
            return {"error": "missing member field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"error": "bad member id"}

    for field in ("amount", "method"):
        if field not in payment:
            return {"error": "missing payment field"}

    status = member["status"]
    if status == "banned":
        return {"error": "member banned"}

    return {"member": member, "payment": payment, "status": status}


def _dispatch(status: str, member: dict, payment: dict) -> dict:
    handler = _STATUS_HANDLERS.get(status)
    if handler is None:
        return {"ok": False, "error": "unknown status"}
    return handler(member, payment)


def _check(condition: bool, error: str) -> dict | None:
    if not condition:
        return {"ok": False, "error": error}
    return None


def _complete(member: dict, payment: dict, fee: int, status: str) -> dict:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    receipt = f"{payment['method']}:{member['id']}:{status}:{fee}"
    return {"ok": True, "status": status, "fee": fee, "receipt": receipt}


def _handle_active(member: dict, payment: dict) -> dict:
    if err := _check(member["tier"] in TIER_FEES, "unknown tier"):
        return err
    if err := _check(isinstance(payment["amount"], int) and payment["amount"] > 0, "bad amount"):
        return err
    if err := _check(payment["method"] in VALID_METHODS, "unsupported method"):
        return err
    fee = TIER_FEES[member["tier"]]
    return _complete(member, payment, fee, "renewed")


def _handle_lapsed(member: dict, payment: dict) -> dict:
