        return err
    if err := _check(
        "expired_days" in member
        and isinstance(member["expired_days"], int)
        and member["expired_days"] >= 0,
        "bad expiry",
    ):
        return err
    if err := _check(isinstance(payment["amount"], int) and payment["amount"] > 0, "bad amount"):
        return err
    if err := _check(payment["method"] in VALID_METHODS, "unsupported method"):
        return err
