        new_status = "renewed"
    else:
        fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
        new_status = "reinstated"
    return _complete(member, payment, fee, new_status)


def _handle_suspended(member: dict, payment: dict) -> dict:
    if err := _check(member["tier"] in TIER_FEES, "unknown tier"):
        return err
    if err := _check(
        "strikes" in member
        and isinstance(member["strikes"], int)
        and member["strikes"] >= 0,
        "bad strikes",
    ):
        return err
    if member["strikes"] >= MAX_STRIKES:
