export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.loyaltyYears;
  if (!Number.isInteger(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  switch (req.category) {
    case "standard": return quoteStandard(req, loyaltyYears as number);
    case "suite": return quoteSuite(req, loyaltyYears as number);
    case "villa": return quoteVilla(req, loyaltyYears as number);
    default: return { ok: false, error: "unknown category" };
  }
}

function validateInt(value: unknown, min: number, max: number): { ok: true; value: number } | { ok: false } {
  if (!Number.isInteger(value) || value < min || value > max) return { ok: false };
  return { ok: true, value: value as number };
}

function quoteStandard(
  req: Record<string, unknown>,
  loyaltyYears: number,
): QuoteResult {
  const nights = validateInt(req.nights, 1, 14);
  if (!nights.ok) return { ok: false, error: "bad nights" };
  const guests = validateInt(req.guests, 1, 2);
  if (!guests.ok) return { ok: false, error: "bad guests" };
  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const total = calcStandardTotal(nights.value, season as "low" | "high", loyaltyYears);
  const policy = calcPolicy(req.coupon, loyaltyYears, 2);
  return { ok: true, total, policy, line: `standard:${nights.value}n:${total}:${policy}` };
}

function quoteSuite(
  req: Record<string, unknown>,
  loyaltyYears: number,
): QuoteResult {
  const nights = validateInt(req.nights, 1, 21);
  if (!nights.ok) return { ok: false, error: "bad nights" };
  const guests = validateInt(req.guests, 1, 4);
  if (!guests.ok) return { ok: false, error: "bad guests" };
  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const total = calcSuiteTotal(nights.value, season as "low" | "high", guests.value, loyaltyYears);
  const policy = calcPolicy(req.coupon, loyaltyYears, 3);
  return { ok: true, total, policy, line: `suite:${nights.value}n:${total}:${policy}` };
}

function quoteVilla(
  req: Record<string, unknown>,
  loyaltyYears: number,
): QuoteResult {
  const nights = validateInt(req.nights, 1, 28);
  if (!nights.ok) return { ok: false, error: "bad nights" };
  if (nights.value < 3) return { ok: false, error: "villa minimum stay" };
  const guests = validateInt(req.guests, 1, 8);
  if (!guests.ok) return { ok: false, error: "bad guests" };
  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }
  const total = calcVillaTotal(nights.value, season as "low" | "high", loyaltyYears);
  const policy = calcPolicy(req.coupon, loyaltyYears, 3);
  return { ok: true, total, policy, line: `villa:${nights.value}n:${total}:${policy}` };
}

function calcStandardTotal(nights: number, season: "low" | "high", loyaltyYears: number): number {
  let total = 80 * nights;
  if (season === "high") total += 30 * nights;
  if (loyaltyYears >= 3 || isVipCoupon) total -= Math.floor(total / 10);
  return total;
}

function calcSuiteTotal(nights: number, season: "low" | "high", guests: number, loyaltyYears: number): number {
  let total = 150 * nights;
  if (season === "high") total += 60 * nights;
  if (isVipCoupon || loyaltyYears >= 3) total -= Math.floor(total / 10);
  if (guests > 2) total += 25;
  return total;
}

function calcVillaTotal(nights: number, season: "low" | "high", loyaltyYears: number): number {
  let total = 300 * nights;
  if (season === "high") total += 120 * nights;
  if (loyaltyYears > 2 || isVipCoupon) total -= Math.floor(total / 10);
  total += 500;
  return total;
}

function calcPolicy(coupon: unknown, loyaltyYears: number, threshold: number): string {
  return isVipCoupon || loyaltyYears > threshold ? "flex" : "strict";
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  category: string;
  baseRate: number;
  seasonSurcharge: number;
  nightLimits: [number, number];
  guestLimits: [number, number];
  extraGuestFee: number;
  extraGuestThreshold: number;
  flatFee: number;
  specialNightMin?: number;
  specialNightMinError?: string;
}

function isIntegerValue(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

function extractNumber(req: Record<string, unknown>, key: string): number | null {
  if (!isIntegerValue(req[key])) {
    return null;
  }
  return req[key];
}

const CATEGORIES: CategoryConfig[] = [
  {
    category: "standard",
    baseRate: 80,
    seasonSurcharge: 30,
    nightLimits: [1, 14],
    guestLimits: [1, 2],
    extraGuestFee: 0,
    extraGuestThreshold: 2,
    flatFee: 0,
  },
  {
    category: "suite",
    baseRate: 150,
    seasonSurcharge: 60,
    nightLimits: [1, 21],
    guestLimits: [1, 4],
    extraGuestFee: 25,
    extraGuestThreshold: 2,
    flatFee: 0,
  },
  {
    category: "villa",
    baseRate: 300,
    seasonSurcharge: 120,
    nightLimits: [1, 28],
    guestLimits: [1, 8],
    extraGuestFee: 0,
    extraGuestThreshold: 0,
    flatFee: 500,
    specialNightMin: 3,
    specialNightMinError: "villa minimum stay",
  },
];

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = extractNumber(req, "loyaltyYears");
  if (loyaltyYears === null || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category;
  if (typeof category !== "string") {
    return { ok: false, error: "unknown category" };
  }

  const config = CATEGORIES.find((c) => c.category === category);
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const nights = extractNumber(req, "nights");
  if (nights === null) {
    return { ok: false, error: "bad nights" };
  }
  if (config.specialNightMin !== undefined && nights < config.specialNightMin) {
    return { ok: false, error: config.specialNightMinError ?? "bad nights" };
  }
  if (nights < config.nightLimits[0] || nights > config.nightLimits[1]) {
    return { ok: false, error: "bad nights" };
  }

  const guests = extractNumber(req, "guests");
  if (guests === null) {
    return { ok: false, error: "bad guests" };
  }
  if (guests < config.guestLimits[0] || guests > config.guestLimits[1]) {
    return { ok: false, error: "bad guests" };
  }

  const season = req.season;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.seasonSurcharge * nights;
  }

  const eligibleForDiscount = loyaltyYears >= 3 || req.coupon === "VIP";
  if (eligibleForDiscount) {
    total -= Math.floor(total / 10);
  }

  if (guests > config.extraGuestThreshold) {
    total += config.extraGuestFee;
  }

  total += config.flatFee;

  const policy = eligibleForDiscount ? "flex" : "strict";

  const line = `${config.category}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

