  policy?: string;
  line?: string;
}

interface BookingRequest {
  category: string;
  loyaltyYears: number;
  nights: number;
  guests: number;
  season: string;
  coupon?: string;
}

function validateInteger(value: unknown): number | null {
  if (!Number.isInteger(value)) {
    return null;
  }
  return value as number;
}

function parseLoyalty(raw: Record<string, unknown>): number | null {
  const years = validateInteger(raw.loyaltyYears);
  if (years === null || years < 0) {
    return null;
  }
  return years;
}

function parseNights(raw: Record<string, unknown>): number | null {
  return validateInteger(raw.nights);
}

function parseGuests(raw: Record<string, unknown>): number | null {
  return validateInteger(raw.guests);
}

function parseSeason(raw: Record<string, unknown>): string | null {
  const season = raw.season;
  if (typeof season !== "string") {
    return null;
  }
  if (season !== "low" && season !== "high") {
    return null;
  }
  return season;
}

function parseCoupon(raw: Record<string, unknown>): string | undefined {
  const coupon = raw.coupon;
  if (typeof coupon === "string") {
    return coupon;
  }
  return undefined;
}

function parseCategory(raw: Record<string, unknown>): string | undefined {
  const cat = raw.category;
  if (typeof cat === "string") {
    return cat;
  }
  return undefined;
}

function parseRequest(raw: unknown): BookingRequest | { ok: false; error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const req = raw as Record<string, unknown>;

  const loyaltyYears = parseLoyalty(req);
  if (loyaltyYears === null) {
    return { ok: false, error: "bad loyalty" };
  }

  const nights = parseNights(req);
  if (nights === null) {
    return { ok: false, error: "bad nights" };
  }

  const guests = parseGuests(req);
  if (guests === null) {
    return { ok: false, error: "bad guests" };
  }

  const season = parseSeason(req);
  if (season === null) {
    return { ok: false, error: "bad season" };
  }

  return {
    category: parseCategory(req) ?? "",
    loyaltyYears,
    nights,
    guests,
    season,
    coupon: parseCoupon(req),
  };
}

interface CategoryConfig {
  prefix: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highSeasonMultiplier: number;
  extraGuestFee: number;
  extraGuestThreshold: number;
  flatFee?: number;
}

const CATEGORY_CONFIGS: Record<string, CategoryConfig> = {
  standard: {
    prefix: "standard",
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
    baseRate: 80,
    highSeasonMultiplier: 30,
    extraGuestFee: 0,
    extraGuestThreshold: Infinity,
  },
  suite: {
    prefix: "suite",
    minNights: 1,
    maxNights: 21,
    minGuests: 1,
    maxGuests: 4,
    baseRate: 150,
    highSeasonMultiplier: 60,
    extraGuestFee: 25,
    extraGuestThreshold: 2,
  },
  villa: {
    prefix: "villa",
    minNights: 3,
    maxNights: 28,
    minGuests: 1,
    maxGuests: 8,
    baseRate: 300,
    highSeasonMultiplier: 120,
    extraGuestFee: 0,
    extraGuestThreshold: Infinity,
    flatFee: 500,
  },
};

function applyDiscount(total: number, loyaltyYears: number, coupon?: string): number {
  if (loyaltyYears >= 3 || coupon === "VIP") {
    return total - Math.floor(total / 10);
  }
  return total;
}

function determinePolicy(loyaltyYears: number, coupon?: string): "strict" | "flex" {
  if (coupon === "VIP" || loyaltyYears >= 3) {
    return "flex";
  }
  return "strict";
}

function buildLine(prefix: string, nights: number, total: number, policy: string): string {
  return `${prefix}:${nights}n:${total}:${policy}`;
}

function calculateQuote(config: CategoryConfig, loyaltyYears: number, nights: number, guests: number, season: string, coupon?: string): QuoteResult {
  let total = config.baseRate * nights;

  if (season === "high") {
    total += config.highSeasonMultiplier * nights;
  }

  total = applyDiscount(total, loyaltyYears, coupon);

  if (guests > config.extraGuestThreshold) {
    total += config.extraGuestFee;
  }

  if (config.flatFee) {
    total += config.flatFee;
  }

  const policy = determinePolicy(loyaltyYears, coupon);
  return { ok: true, total, policy, line: buildLine(config.prefix, nights, total, policy) };
}

function isVillaMinimumStay(category: string, nights: number): boolean {
  return category === "villa" && nights < 3;
}

export function quoteBooking(raw: unknown): QuoteResult {
  const validated = parseRequest(raw);
  if (!validated.ok) {
    return { ok: false, error: validated.error };
  }

  const { category, loyaltyYears, nights, guests, season, coupon } = validated;
  const config = CATEGORY_CONFIGS[category];

  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  if (nights < config.minNights || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }

  if (guests < config.minGuests || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }

  if (isVillaMinimumStay(category, nights)) {
    return { ok: false, error: "villa minimum stay" };
  }

  return calculateQuote(config, loyaltyYears, nights, guests, season, coupon);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface BookingRequest {
  loyaltyYears: number;
  category: string;
  nights: number;
  guests: number;
  season: string;
  coupon?: string;
}

function isDiscountEligible(loyaltyYears: number, coupon?: string): boolean {
  return loyaltyYears >= 3 || coupon === "VIP";
}

function isFlexPolicy(loyaltyYears: number, coupon?: string): boolean {
  return coupon === "VIP" || loyaltyYears >= 3;
}

function validateSeason(season: string): boolean {
  return season === "low" || season === "high";
}

function validateNights(nights: number, min: number, max: number): boolean {
  return Number.isInteger(nights) && nights >= min && nights <= max;
}

function validateGuests(guests: number, max: number): boolean {
  return Number.isInteger(guests) && guests >= 1 && guests <= max;
}

function validateStandard(req: BookingRequest): QuoteResult {
  if (!validateNights(req.nights, 1, 14)) {
    return { ok: false, error: "bad nights" };
  }
  if (!validateGuests(req.guests, 2)) {
    return { ok: false, error: "bad guests" };
  }
  if (!validateSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const total = computeStandardTotal(req);
  const policy = isFlexPolicy(req.loyaltyYears, req.coupon) ? "flex" : "strict";
  return {
    ok: true,
    total,
    policy,
    line: `standard:${req.nights}n:${total}:${policy}`,
  };
}

function computeStandardTotal(req: BookingRequest): number {
  let total = 80 * req.nights;
  if (req.season === "high") {
    total += 30 * req.nights;
  }
  if (isDiscountEligible(req.loyaltyYears, req.coupon)) {
    total -= Math.floor(total / 10);
  }
  return total;
}

function validateSuite(req: BookingRequest): QuoteResult {
  if (!validateNights(req.nights, 1, 21)) {
    return { ok: false, error: "bad nights" };
  }
  if (!validateGuests(req.guests, 4)) {
    return { ok: false, error: "bad guests" };
  }
  if (!validateSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const total = computeSuiteTotal(req);
  const policy = isFlexPolicy(req.loyaltyYears, req.coupon) ? "flex" : "strict";
  return {
    ok: true,
    total,
    policy,
    line: `suite:${req.nights}n:${total}:${policy}`,
  };
}

function computeSuiteTotal(req: BookingRequest): number {
  let total = 150 * req.nights;
  if (req.season === "high") {
    total += 60 * req.nights;
  }
  if (isDiscountEligible(req.loyaltyYears, req.coupon)) {
    total -= Math.floor(total / 10);
  }
  if (req.guests > 2) {
    total += 25;
  }
  return total;
}

function validateVilla(req: BookingRequest): QuoteResult {
  if (!validateNights(req.nights, 1, 28)) {
    return { ok: false, error: "bad nights" };
  }
  if (req.nights < 3) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!validateGuests(req.guests, 8)) {
    return { ok: false, error: "bad guests" };
  }
  if (!validateSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  const total = computeVillaTotal(req);
  const policy = isFlexPolicy(req.loyaltyYears, req.coupon) ? "flex" : "strict";
  return {
    ok: true,
    total,
    policy,
    line: `villa:${req.nights}n:${total}:${policy}`,
  };
}

function computeVillaTotal(req: BookingRequest): number {
  let total = 300 * req.nights;
  if (req.season === "high") {
    total += 120 * req.nights;
  }
  if (isDiscountEligible(req.loyaltyYears, req.coupon)) {
    total -= Math.floor(total / 10);
  }
  total += 500;
  return total;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as BookingRequest;

  if (!Number.isInteger(req.loyaltyYears) || req.loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  switch (req.category) {
    case "standard":
      return validateStandard(req);
    case "suite":
      return validateSuite(req);
    case "villa":
      return validateVilla(req);
    default:
      return { ok: false, error: "unknown category" };
  }
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface BookingRequest {
  loyaltyYears: number;
  category: string;
  nights: number;
  guests: number;
  season: string;
  coupon?: unknown;
}

interface CategoryConfig {
  name: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highRate: number;
  extraFlat: number;
  extraGuests: boolean;
  extraGuestThreshold: number;
}

interface ValidationRule<Req> {
  test: (value: unknown, req: Req) => boolean;
  error: string;
}

const VALID_SEASONS = ["low", "high"];
const DISCOUNT_THRESHOLD = 3;
const VIP_COUPON = "VIP";
const EXTRA_GUEST_FEE = 25;

const CATEGORIES: Record<string, CategoryConfig> = {
  standard: {
    name: "standard",
    minNights: 1, maxNights: 14,
    minGuests: 1, maxGuests: 2,
    baseRate: 80, highRate: 30,
    extraFlat: 0, extraGuests: false, extraGuestThreshold: 2,
  },
  suite: {
    name: "suite",
    minNights: 1, maxNights: 21,
    minGuests: 1, maxGuests: 4,
    baseRate: 150, highRate: 60,
    extraFlat: 0, extraGuests: true, extraGuestThreshold: 2,
  },
  villa: {
    name: "villa",
    minNights: 3, maxNights: 28,
    minGuests: 1, maxGuests: 8,
    baseRate: 300, highRate: 120,
    extraFlat: 500, extraGuests: false, extraGuestThreshold: 2,
  },
};

function isSeasonValid(season: unknown): boolean {
  return typeof season === "string" && VALID_SEASONS.includes(season);
}

function isDiscountEligible(loyaltyYears: number, coupon: unknown): boolean {
  return loyaltyYears >= DISCOUNT_THRESHOLD || coupon === VIP_COUPON;
}

function computeTotal(cfg: CategoryConfig, nights: number, season: string, guests: number, loyaltyYears: number, coupon: unknown): number {
  let total = cfg.baseRate * nights;
  if (season === "high") {
    total += cfg.highRate * nights;
  }
  if (isDiscountEligible(loyaltyYears, coupon)) {
    total -= Math.floor(total / 10);
  }
  if (cfg.extraGuests && guests > cfg.extraGuestThreshold) {
    total += EXTRA_GUEST_FEE;
  }
  total += cfg.extraFlat;
  return total;
}

function computePolicy(loyaltyYears: number, coupon: unknown): "strict" | "flex" {
  return isDiscountEligible(loyaltyYears, coupon) ? "flex" : "strict";
}

function formatLine(cfg: CategoryConfig, nights: number, total: number, policy: string): string {
  return `${cfg.name}:${nights}n:${total}:${policy}`;
}

function processBooking(req: BookingRequest): QuoteResult {
  const cfg = CATEGORIES[req.category];
  const total = computeTotal(cfg, req.nights, req.season, req.guests, req.loyaltyYears, req.coupon);
  const policy = computePolicy(req.loyaltyYears, req.coupon);
  const line = formatLine(cfg, req.nights, total, policy);
  return { ok: true, total, policy, line };
}

function validateAndBuild(raw: unknown): QuoteResult | BookingRequest | null {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const req = raw as Record<string, unknown>;
  const category = req.category;
  if (typeof category !== "string" || !(category in CATEGORIES)) {
    return { ok: false, error: "unknown category" };
  }

  const cfg = CATEGORIES[category];
  const checks: { test: (v: unknown) => boolean; error: string }[] = [
    { test: (v) => Number.isInteger(v) && (v as number) >= 0, error: "bad loyalty" },
    { test: (v) => Number.isInteger(v) && (v as number) >= cfg.minNights && (v as number) <= cfg.maxNights, error: "bad nights" },
    { test: (v) => Number.isInteger(v) && (v as number) >= cfg.minGuests && (v as number) <= cfg.maxGuests, error: "bad guests" },
    { test: isSeasonValid, error: "bad season" }
  ];

  const fields = [req.loyaltyYears, req.nights, req.guests, req.season];
  for (let i = 0; i < fields.length; i++) {
    if (!checks[i].test(fields[i])) {
      return { ok: false, error: checks[i].error };
    }
  }

  return {
    loyaltyYears: req.loyaltyYears as number,
    category: category,
    nights: req.nights as number,
    guests: req.guests as number,
    season: req.season as string,
    coupon: req.coupon,
  };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const validated = validateAndBuild(raw);
  if (validated && typeof validated === "object" && "ok" in validated && !validated.ok) {
    return validated as QuoteResult;
  }
  if (validated) {
    return processBooking(validated as BookingRequest);
  }
  return { ok: false, error: "malformed request" };
}

