export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventDefinition {
  status: string;
  extractId: (data: Record<string, unknown>) => string;
  buildMessage: (id: string) => string;
}

const EVENT_REGISTRY: Record<string, EventDefinition> = {
  "user.created":  { status: "ok",        extractId: (d) => String(d.id),         buildMessage: (id) => `created user ${id}` },
  "user.updated":  { status: "ok",        extractId: (d) => String(d.id),         buildMessage: (id) => `updated user ${id}` },
  "user.deleted":  { status: "ok",        extractId: (d) => String(d.id),         buildMessage: (id) => `deleted user ${id}` },
  "order.placed":  { status: "ok",        extractId: (d) => String(d.orderId),    buildMessage: (id) => `order placed ${id}` },
  "order.cancelled": { status: "ok",      extractId: (d) => String(d.orderId),    buildMessage: (id) => `order cancelled ${id}` },
  "order.shipped": { status: "ok",        extractId: (d) => String(d.orderId),    buildMessage: (id) => `order shipped ${id}` },
  "payment.succeeded": { status: "ok",    extractId: (d) => String(d.paymentId),  buildMessage: (id) => `payment succeeded ${id}` },
  "payment.failed":  { status: "error",   extractId: (d) => String(d.paymentId),  buildMessage: (id) => `payment failed ${id}` },
  "invoice.issued":  { status: "ok",      extractId: (d) => String(d.invoiceId),  buildMessage: (id) => `invoice issued ${id}` },
  "invoice.voided":  { status: "ok",      extractId: (d) => String(d.invoiceId),  buildMessage: (id) => `invoice voided ${id}` },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const definition = EVENT_REGISTRY[name];
  if (!definition) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  return {
    status: definition.status,
    message: definition.buildMessage(definition.extractId(payload.data)),
  };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventRoute {
  message: string;
  status: string;
  field: string;
}

const EVENT_ROUTES: Record<string, EventRoute> = {
  "user.created":  { status: "ok", message: `created user`,   field: "id" },
  "user.updated":  { status: "ok", message: `updated user`,   field: "id" },
  "user.deleted":  { status: "ok", message: `deleted user`,   field: "id" },
  "order.placed":  { status: "ok", message: `order placed`,   field: "orderId" },
  "order.cancelled": { status: "ok", message: `order cancelled`, field: "orderId" },
  "order.shipped": { status: "ok", message: `order shipped`,  field: "orderId" },
  "payment.succeeded": { status: "ok", message: `payment succeeded`, field: "paymentId" },
  "payment.failed":  { status: "error", message: `payment failed`, field: "paymentId" },
  "invoice.issued": { status: "ok", message: `invoice issued`, field: "invoiceId" },
  "invoice.voided": { status: "ok", message: `invoice voided`, field: "invoiceId" },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const route = EVENT_ROUTES[name];
  if (route) {
    const idValue = String(payload.data[route.field]);
    return { status: route.status, message: `${route.message} ${idValue}` };
  }
  return { status: "error", message: `unknown event: ${name}` };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventRoute {
  message: (data: Record<string, unknown>) => string;
  status?: string;
}

const EVENT_ROUTES: Record<string, EventRoute> = {
  "user.created":  { message: (data) => `created user ${String(data.id)}` },
  "user.updated":  { message: (data) => `updated user ${String(data.id)}` },
  "user.deleted":  { message: (data) => `deleted user ${String(data.id)}` },
  "order.placed":  { message: (data) => `order placed ${String(data.orderId)}` },
  "order.cancelled": { message: (data) => `order cancelled ${String(data.orderId)}` },
  "order.shipped": { message: (data) => `order shipped ${String(data.orderId)}` },
  "payment.succeeded": { message: (data) => `payment succeeded ${String(data.paymentId)}` },
  "payment.failed":  { message: (data) => `payment failed ${String(data.paymentId)}`, status: "error" },
  "invoice.issued":  { message: (data) => `invoice issued ${String(data.invoiceId)}` },
  "invoice.voided":  { message: (data) => `invoice voided ${String(data.invoiceId)}` },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const route = EVENT_ROUTES[name];
  if (!route) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  return {
    status: route.status ?? "ok",
    message: route.message(payload.data),
  };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const defaultFormatter = (id: string): string => `unknown event: ${id}`;

  const handlers: Record<string, { formatter: (data: Record<string, unknown>) => string; status: string }> = {
    "user.created":     { formatter: (d) => `created user ${String(d.id)}`,     status: "ok" },
    "user.updated":     { formatter: (d) => `updated user ${String(d.id)}`,     status: "ok" },
    "user.deleted":     { formatter: (d) => `deleted user ${String(d.id)}`,     status: "ok" },
    "order.placed":     { formatter: (d) => `order placed ${String(d.orderId)}`, status: "ok" },
    "order.cancelled":  { formatter: (d) => `order cancelled ${String(d.orderId)}`, status: "ok" },
    "order.shipped":    { formatter: (d) => `order shipped ${String(d.orderId)}`, status: "ok" },
    "payment.succeeded":{ formatter: (d) => `payment succeeded ${String(d.paymentId)}`, status: "ok" },
    "payment.failed":   { formatter: (d) => `payment failed ${String(d.paymentId)}`,  status: "error" },
    "invoice.issued":   { formatter: (d) => `invoice issued ${String(d.invoiceId)}`, status: "ok" },
    "invoice.voided":   { formatter: (d) => `invoice voided ${String(d.invoiceId)}`, status: "ok" },
  };

  const entry = handlers[name];
  if (entry) {
    return { status: entry.status, message: entry.formatter(payload.data) };
  }

  return { status: "error", message: defaultFormatter(name) };
}

