      if (loyaltyYears >= 3 || coupon === "VIP") total -= Math.floor(total / 10);
      total += 500;
      const policy = coupon === "VIP" || loyaltyYears >= 3 ? "flex" : "strict";
      return { ok: true, total, policy, line: `villa:${nights}n:${total}:${policy}` };
    },
  },
};

function quoteStandard(req: Record<string, unknown>): QuoteResult {
  const nights = safeInt(req, "nights");
  if (nights === undefined || nights < 1 || nights > 14) return { ok: false, error: "bad nights" };
  const guests = safeInt(req, "guests");
  if (guests === undefined || guests < 1 || guests > 2) return { ok: false, error: "bad guests" };
  if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
  const loyaltyYears = safeInt(req, "loyaltyYears");
  if (loyaltyYears === undefined || loyaltyYears < 0) return { ok: false, error: "bad loyalty" };
  return CATEGORIES.standard.quote({ nights, guests, season: req.season as string, loyaltyYears, coupon: (req.coupon as string) ?? "" });
}

function quoteSuite(req: Record<string, unknown>): QuoteResult {
  const nights = safeInt(req, "nights");
  if (nights === undefined || nights < 1 || nights > 21) return { ok: false, error: "bad nights" };
  const guests = safeInt(req, "guests");
  if (guests === undefined || guests < 1 || guests > 4) return { ok: false, error: "bad guests" };
  if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
  const loyaltyYears = safeInt(req, "loyaltyYears");
  if (loyaltyYears === undefined || loyaltyYears < 0) return { ok: false, error: "bad loyalty" };
  return CATEGORIES.suite.quote({ nights, guests, season: req.season as string, loyaltyYears, coupon: (req.coupon as string) ?? "" });
}

function quoteVilla(req: Record<string, unknown>): QuoteResult {
  const nights = safeInt(req, "nights");
  if (nights === undefined || nights < 1 || nights > 28) return { ok: false, error: "bad nights" };
  if (nights < 3) return { ok: false, error: "villa minimum stay" };
  const guests = safeInt(req, "guests");
  if (guests === undefined || guests < 1 || guests > 8) return { ok: false, error: "bad guests" };
  if (req.season !== "low" && req.season !== "high") return { ok: false, error: "bad season" };
  const loyaltyYears = safeInt(req, "loyaltyYears");
  if (loyaltyYears === undefined || loyaltyYears < 0) return { ok: false, error: "bad loyalty" };
  return CATEGORIES.villa.quote({ nights, guests, season: req.season as string, loyaltyYears, coupon: (req.coupon as string) ?? "" });
}

function safeInt(req: Record<string, unknown>, key: string): number | undefined {
  const val = req[key];
  return typeof val === "number" && Number.isInteger(val) ? val : undefined;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const category = req.category;
  if (typeof category !== "string") {
    return { ok: false, error: "unknown category" };
  }
  switch (category) {
    case "standard": return quoteStandard(req);
    case "suite": return quoteSuite(req);
    case "villa": return quoteVilla(req);
    default: return { ok: false, error: "unknown category" };
  }
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  prefix: string;
  baseRate: number;
  highSeasonSurcharge: number;
  maxNights: number;
  minNights: number;
  maxGuests: number;
  extraGuestFee: number;
  fixedFee: number;
}

const CATEGORY_CONFIGS: Record<string, CategoryConfig> = {
  standard: {
    prefix: "standard",
    baseRate: 80,
    highSeasonSurcharge: 30,
    maxNights: 14,
    minNights: 1,
    maxGuests: 2,
    extraGuestFee: 0,
    fixedFee: 0,
  },
  suite: {
    prefix: "suite",
    baseRate: 150,
    highSeasonSurcharge: 60,
    maxNights: 21,
    minNights: 1,
    maxGuests: 4,
    extraGuestFee: 25,
    fixedFee: 0,
  },
  villa: {
    prefix: "villa",
    baseRate: 300,
    highSeasonSurcharge: 120,
    maxNights: 28,
    minNights: 3,
    maxGuests: 8,
    extraGuestFee: 0,
    fixedFee: 500,
  },
};

type Rule = (req: Record<string, unknown>) => string | null;

function runRules(req: Record<string, unknown>, rules: Rule[]): string | null {
  for (const rule of rules) {
    const error = rule(req);
    if (error) return error;
  }
  return null;
}

interface ParsedRequest {
  loyaltyYears: number;
  config: CategoryConfig;
  nights: number;
  guests: number;
  season: "low" | "high";
  coupon?: string;
}

function parseRequest(raw: unknown): ParsedRequest | { error: string } {
  if (typeof raw !== "object" || raw === null) {
    return { error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const rules: Rule[] = [
    (r) => {
      const loyaltyYears = r.loyaltyYears as number;
      if (!Number.isInteger(loyaltyYears) || loyaltyYears < 0) return "bad loyalty";
      return null;
    },
    (r) => {
      const category = r.category;
      if (typeof category !== "string") return "unknown category";
      if (!CATEGORY_CONFIGS[category]) return "unknown category";
      return null;
    },
    (r) => {
      const category = r.category as string;
      const config = CATEGORY_CONFIGS[category];
      const nights = r.nights as number;
      if (!Number.isInteger(nights) || nights < config.minNights || nights > config.maxNights) return "bad nights";
      return null;
    },
    (r) => {
      const category = r.category as string;
      const config = CATEGORY_CONFIGS[category];
      const guests = r.guests as number;
      if (!Number.isInteger(guests) || guests < 1 || guests > config.maxGuests) return "bad guests";
      return null;
    },
    (r) => {
      const season = r.season;
      if (season !== "low" && season !== "high") return "bad season";
      return null;
    },
  ];

  const error = runRules(req, rules);
  if (error) return { error };

  const category = req.category as string;
  const config = CATEGORY_CONFIGS[category];
  const loyaltyYears = req.loyaltyYears as number;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as "low" | "high";
  const coupon = typeof req.coupon === "string" ? req.coupon : undefined;

  return { loyaltyYears, config, nights, guests, season, coupon };
}

function computeQuote(parsed: ParsedRequest): QuoteResult {
  let total = parsed.config.baseRate * parsed.nights;
  if (parsed.season === "high") {
    total += parsed.config.highSeasonSurcharge * parsed.nights;
  }
  if (parsed.guests > 2) {
    total += parsed.config.extraGuestFee;
  }
  total += parsed.config.fixedFee;

  if (parsed.loyaltyYears >= 3 || parsed.coupon === "VIP") {
    total = total - Math.floor(total / 10);
  }

  const policy = (parsed.coupon === "VIP" || parsed.loyaltyYears >= 3)
    ? "flex"
    : "strict";

  const line = `${parsed.config.prefix}:${parsed.nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  const parsed = parseRequest(raw);
  if ("error" in parsed) {
    return { ok: false, error: parsed.error };
  }
  return computeQuote(parsed);
}

