export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventHandler {
  prefix: string;
  idKey: string;
  status?: string;
}

const eventConfig: Record<string, EventHandler> = {
  "user.created":   { prefix: "created user",   idKey: "id" },
  "user.updated":   { prefix: "updated user",   idKey: "id" },
  "user.deleted":   { prefix: "deleted user",   idKey: "id" },
  "order.placed":   { prefix: "order placed",   idKey: "orderId" },
  "order.cancelled": { prefix: "order cancelled", idKey: "orderId" },
  "order.shipped":  { prefix: "order shipped",  idKey: "orderId" },
  "payment.succeeded": { prefix: "payment succeeded", idKey: "paymentId" },
  "payment.failed":  { prefix: "payment failed", idKey: "paymentId", status: "error" },
  "invoice.issued":  { prefix: "invoice issued", idKey: "invoiceId" },
  "invoice.voided":  { prefix: "invoice voided", idKey: "invoiceId" },
};

function buildMessage(config: EventHandler, payload: EventPayload): string {
  return `${config.prefix} ${String(payload.data[config.idKey])}`;
}

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const config = eventConfig[name];

  if (!config) {
    return { status: "error", message: `unknown event: ${name}` };
  }

  return {
    status: config.status ?? "ok",
    message: buildMessage(config, payload),
  };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventDefinition {
  template: (data: Record<string, unknown>) => string;
  defaultStatus?: string;
  status?: (data: Record<string, unknown>) => string;
}

const EVENT_REGISTRY: Record<string, EventDefinition> = {
  "user.created":    { template: (d) => `created user ${String(d.id)}` },
  "user.updated":    { template: (d) => `updated user ${String(d.id)}` },
  "user.deleted":    { template: (d) => `deleted user ${String(d.id)}` },
  "order.placed":    { template: (d) => `order placed ${String(d.orderId)}` },
  "order.cancelled": { template: (d) => `order cancelled ${String(d.orderId)}` },
  "order.shipped":   { template: (d) => `order shipped ${String(d.orderId)}` },
  "payment.succeeded": { template: (d) => `payment succeeded ${String(d.paymentId)}` },
  "payment.failed":  { template: (d) => `payment failed ${String(d.paymentId)}`, defaultStatus: "error" },
  "invoice.issued":  { template: (d) => `invoice issued ${String(d.invoiceId)}` },
  "invoice.voided":  { template: (d) => `invoice voided ${String(d.invoiceId)}` },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const definition = EVENT_REGISTRY[name];
  if (!definition) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  return {
    status: definition.defaultStatus ?? "ok",
    message: definition.template(payload.data),
  };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

const EVENT_CONFIG: Record<string, { action: string; key: string; okStatus: string }> = {
  "user.created":  { action: "created user",  key: "id",        okStatus: "ok" },
  "user.updated":  { action: "updated user",  key: "id",        okStatus: "ok" },
  "user.deleted":  { action: "deleted user",  key: "id",        okStatus: "ok" },
  "order.placed":  { action: "order placed",  key: "orderId",   okStatus: "ok" },
  "order.cancelled": { action: "order cancelled", key: "orderId", okStatus: "ok" },
  "order.shipped": { action: "order shipped", key: "orderId",   okStatus: "ok" },
  "payment.succeeded": { action: "payment succeeded", key: "paymentId", okStatus: "ok" },
  "payment.failed":  { action: "payment failed",  key: "paymentId", okStatus: "error" },
  "invoice.issued":  { action: "invoice issued",  key: "invoiceId", okStatus: "ok" },
  "invoice.voided":  { action: "invoice voided",  key: "invoiceId", okStatus: "ok" },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const config = EVENT_CONFIG[name];
  if (!config) {
    return { status: "error", message: `unknown event: ${name}` };
  }

  return {
    status: config.okStatus,
    message: `${config.action} ${String(payload.data[config.key])}`,
  };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface EventHandlerConfig {
  idKey: string;
  template: string;
  status: string;
}

const EVENT_CONFIGS: Record<string, EventHandlerConfig> = {
  "user.created":      { idKey: "id",     template: "created user {id}",   status: "ok" },
  "user.updated":      { idKey: "id",     template: "updated user {id}",   status: "ok" },
  "user.deleted":      { idKey: "id",     template: "deleted user {id}",   status: "ok" },
  "order.placed":      { idKey: "orderId",  template: "order placed {id}", status: "ok" },
  "order.cancelled":   { idKey: "orderId",  template: "order cancelled {id}", status: "ok" },
  "order.shipped":     { idKey: "orderId",  template: "order shipped {id}", status: "ok" },
  "payment.succeeded": { idKey: "paymentId", template: "payment succeeded {id}", status: "ok" },
  "payment.failed":    { idKey: "paymentId", template: "payment failed {id}", status: "error" },
  "invoice.issued":    { idKey: "invoiceId",  template: "invoice issued {id}", status: "ok" },
  "invoice.voided":    { idKey: "invoiceId",  template: "invoice voided {id}", status: "ok" },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const config = EVENT_CONFIGS[name];
  if (!config) {
    return { status: "error", message: `unknown event: ${name}` };
  }

  const id = String(payload.data[config.idKey]);
  return {
    status: config.status,
    message: config.template.replace("{id}", id),
  };
}

