export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

type FlagHandler = (config: FlagConfig, nextArg: string | undefined) => void;

const handlers: Record<string, FlagHandler> = {
  "--verbose": (config) => { config.verbose = true; },
  "--quiet": (config) => { config.quiet = true; },
  "--dry-run": (config) => { config.dryRun = true; },
  "--force": (config) => { config.force = true; },
  "--no-color": (config) => { config.color = false; },
  "--strict": (config) => { config.strict = true; },
  "--output": (config, nextArg) => {
    if (nextArg === undefined) throw new Error("--output requires a path");
    config.outputPath = nextArg;
  },
  "--config": (config, nextArg) => {
    if (nextArg === undefined) throw new Error("--config requires a path");
    config.configPath = nextArg;
  },
  "--format": (config, nextArg) => {
    if (nextArg === undefined || !VALID_FORMATS.includes(nextArg as VALID_FORMATS[number])) {
      throw new Error(`unsupported format: ${String(nextArg)}`);
    }
    config.format = nextArg;
  },
  "--log-level": (config, nextArg) => {
    if (nextArg === undefined || !VALID_LOG_LEVELS.includes(nextArg as VALID_LOG_LEVELS[number])) {
      throw new Error(`unsupported log level: ${String(nextArg)}`);
    }
    config.logLevel = nextArg;
  },
  "--retries": (config, nextArg) => {
    const value = Number(nextArg);
    if (!Number.isInteger(value)) throw new Error("--retries must be an integer");
    config.maxRetries = value;
  },
  "--timeout": (config, nextArg) => {
    const value = Number(nextArg);
    if (!Number.isInteger(value)) throw new Error("--timeout must be an integer");
    config.timeoutMs = value;
  },
  "--parallel": (config, nextArg) => {
    const value = Number(nextArg);
    if (!Number.isInteger(value)) throw new Error("--parallel must be an integer");
    config.parallelism = value;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const flag = normalizeFlag(argv[i]!);
    const handler = handlers[flag];
    if (handler) {
      handler(config, argv[++i]);
    } else {
      throw new Error(`unknown flag: ${flag}`);
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function validateNumber(value: string | undefined, flagName: string): number {
  const num = Number(value);
  if (!Number.isInteger(num)) {
    throw new Error(`${flagName} must be an integer`);
  }
  return num;
}

type FlagHandler = (config: FlagConfig, argv: string[], index: number) => number;

const FLAG_HANDLERS: Readonly<Record<string, FlagHandler>> = {
  "--verbose": (config) => {
    config.verbose = true;
    return 0;
  },

  "--quiet": (config) => {
    config.quiet = true;
    return 0;
  },

  "--dry-run": (config) => {
    config.dryRun = true;
    return 0;
  },

  "--force": (config) => {
    config.force = true;
    return 0;
  },

  "--no-color": (config) => {
    config.color = false;
    return 0;
  },

  "--strict": (config) => {
    config.strict = true;
    return 0;
  },

  "--output": (config, argv, i) => {
    const value = argv[i + 1];
    if (value === undefined) {
      throw new Error("--output requires a path");
    }
    config.outputPath = value;
    return 1;
  },

  "--config": (config, argv, i) => {
    const value = argv[i + 1];
    if (value === undefined) {
      throw new Error("--config requires a path");
    }
    config.configPath = value;
    return 1;
  },

  "--format": (config, argv, i) => {
    const value = argv[i + 1];
    if (value === undefined || !["json", "yaml", "text"].includes(value)) {
      throw new Error(`unsupported format: ${String(value)}`);
    }
    config.format = value;
    return 1;
  },

  "--log-level": (config, argv, i) => {
    const value = argv[i + 1];
    if (value === undefined || !["debug", "info", "warn", "error"].includes(value)) {
      throw new Error(`unsupported log level: ${String(value)}`);
    }
    config.logLevel = value;
    return 1;
  },

  "--retries": (config, argv, i) => {
    config.maxRetries = validateNumber(argv[i + 1], "--retries");
    return 1;
  },

  "--timeout": (config, argv, i) => {
    config.timeoutMs = validateNumber(argv[i + 1], "--timeout");
    return 1;
  },

  "--parallel": (config, argv, i) => {
    config.parallelism = validateNumber(argv[i + 1], "--parallel");
    return 1;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const handler = FLAG_HANDLERS[arg];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    i += handler(config, argv, i);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: ReadonlyMap<string, string> = new Map([
  ["-v", "--verbose"],
  ["-q", "--quiet"],
  ["-f", "--force"],
  ["-o", "--output"],
]);

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function normalizeFlag(arg: string): string {
  return ALIASES.get(arg) ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

type FlagHandler = (argv: string[], i: number, flag: string, config: FlagConfig) => number;

function validateEnumValue(value: string, label: string, valid: readonly string[]): string {
  if (!valid.includes(value)) {
    throw new Error(`unsupported ${label}: ${value}`);
  }
  return value;
}

function parseIntArg(argv: string[], i: number, flag: string): number {
  const value = argv[i + 1];
  if (value === undefined) {
    throw new Error(`${flag} requires a value`);
  }
  const num = Number(value);
  if (!Number.isInteger(num)) {
    throw new Error(`${flag} must be an integer`);
  }
  return num;
}

function nextStringArg(argv: string[], i: number, flag: string): string {
  const value = argv[i + 1];
  if (value === undefined) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

const handlers: ReadonlyMap<string, FlagHandler> = new Map([
  ["--verbose", (_argv, i, _flag, config) => { config.verbose = true; return i; }],
  ["--quiet", (_argv, i, _flag, config) => { config.quiet = true; return i; }],
  ["--dry-run", (_argv, i, _flag, config) => { config.dryRun = true; return i; }],
  ["--force", (_argv, i, _flag, config) => { config.force = true; return i; }],
  ["--no-color", (_argv, i, _flag, config) => { config.color = false; return i; }],
  ["--strict", (_argv, i, _flag, config) => { config.strict = true; return i; }],
  ["--output", (argv, i, flag, config) => { config.outputPath = nextStringArg(argv, i, flag); return i + 1; }],
  ["--config", (argv, i, flag, config) => { config.configPath = nextStringArg(argv, i, flag); return i + 1; }],
  ["--format", (argv, i, flag, config) => { config.format = validateEnumValue(nextStringArg(argv, i, flag), "format", VALID_FORMATS); return i + 1; }],
  ["--log-level", (argv, i, flag, config) => { config.logLevel = validateEnumValue(nextStringArg(argv, i, flag), "log level", VALID_LOG_LEVELS); return i + 1; }],
  ["--retries", (argv, i, flag, config) => { config.maxRetries = parseIntArg(argv, i, flag); return i + 1; }],
  ["--timeout", (argv, i, flag, config) => { config.timeoutMs = parseIntArg(argv, i, flag); return i + 1; }],
  ["--parallel", (argv, i, flag, config) => { config.parallelism = parseIntArg(argv, i, flag); return i + 1; }],
]);

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = handlers.get(arg);

    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    i = handler(argv, i, arg, config);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeAlias(arg: string): string {
  if (arg.startsWith("-") && arg in ALIASES) {
    return ALIASES[arg]!;
  }
  return arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

interface FlagHandler {
  handler(config: FlagConfig, args: string[], index: number): number;
}

const FLAG_HANDLERS: Record<string, FlagHandler> = {
  "--verbose": {
    handler(config) {
      config.verbose = true;
      return 0;
    },
  },
  "--quiet": {
    handler(config) {
      config.quiet = true;
      return 0;
    },
  },
  "--dry-run": {
    handler(config) {
      config.dryRun = true;
      return 0;
    },
  },
  "--force": {
    handler(config) {
      config.force = true;
      return 0;
    },
  },
  "--no-color": {
    handler(config) {
      config.color = false;
      return 0;
    },
  },
  "--strict": {
    handler(config) {
      config.strict = true;
      return 0;
    },
  },
  "--output": {
    handler(config, args, index) {
      const value = args[index + 1];
      if (value === undefined) {
        throw new Error("--output requires a path");
      }
      config.outputPath = value;
      return 1;
    },
  },
  "--config": {
    handler(config, args, index) {
      const value = args[index + 1];
      if (value === undefined) {
        throw new Error("--config requires a path");
      }
      config.configPath = value;
      return 1;
    },
  },
  "--format": {
    handler(config, args, index) {
      const value = args[index + 1];
      if (value === undefined || !["json", "yaml", "text"].includes(value)) {
        throw new Error(`unsupported format: ${String(value)}`);
      }
      config.format = value;
      return 1;
    },
  },
  "--log-level": {
    handler(config, args, index) {
      const value = args[index + 1];
      if (value === undefined || !["debug", "info", "warn", "error"].includes(value)) {
        throw new Error(`unsupported log level: ${String(value)}`);
      }
      config.logLevel = value;
      return 1;
    },
  },
  "--retries": {
    handler(config, args, index) {
      const value = Number(args[index + 1]);
      if (!Number.isInteger(value)) {
        throw new Error("--retries must be an integer");
      }
      config.maxRetries = value;
      return 1;
    },
  },
  "--timeout": {
    handler(config, args, index) {
      const value = Number(args[index + 1]);
      if (!Number.isInteger(value)) {
        throw new Error("--timeout must be an integer");
      }
      config.timeoutMs = value;
      return 1;
    },
  },
  "--parallel": {
    handler(config, args, index) {
      const value = Number(args[index + 1]);
      if (!Number.isInteger(value)) {
        throw new Error("--parallel must be an integer");
      }
      config.parallelism = value;
      return 1;
    },
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const normalized = normalizeAlias(argv[i]!);
    const handler = FLAG_HANDLERS[normalized];

    if (handler) {
      i += handler.handler(config, argv, i);
    } else {
      throw new Error(`unknown flag: ${normalized}`);
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: ReadonlyMap<string, string> = new Map([
  ["-v", "--verbose"],
  ["-q", "--quiet"],
  ["-f", "--force"],
  ["-o", "--output"],
]);

function normalizeFlag(arg: string): string {
  return ALIASES.get(arg) ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

const FLAGS_WITH_VALUE = new Set<string>([
  "--output",
  "--config",
  "--format",
  "--log-level",
  "--retries",
  "--timeout",
  "--parallel",
]);

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function assertValue(nextArg: string | undefined, flagName: string): string {
  if (nextArg === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  return nextArg;
}

function parsePositiveInteger(raw: string, flagName: string): number {
  const value = Number(raw);
  if (!Number.isInteger(value) || value <= 0) {
    throw new Error(`${flagName} must be a positive integer`);
  }
  return value;
}

type Handler = (config: FlagConfig, value: string) => void;

const HANDLERS: ReadonlyMap<string, Handler> = new Map([
  ["--verbose", (config) => { config.verbose = true; }],
  ["--quiet", (config) => { config.quiet = true; }],
  ["--dry-run", (config) => { config.dryRun = true; }],
  ["--force", (config) => { config.force = true; }],
  ["--no-color", (config) => { config.color = false; }],
  ["--strict", (config) => { config.strict = true; }],
  ["--output", (config, value) => { config.outputPath = value; }],
  ["--config", (config, value) => { config.configPath = value; }],
  ["--format", (config, value) => {
    if (!VALID_FORMATS.includes(value as typeof VALID_FORMATS[number])) {
      throw new Error(`unsupported format: ${value}`);
    }
    config.format = value;
  }],
  ["--log-level", (config, value) => {
    if (!VALID_LOG_LEVELS.includes(value as typeof VALID_LOG_LEVELS[number])) {
      throw new Error(`unsupported log level: ${value}`);
    }
    config.logLevel = value;
  }],
  ["--retries", (config, value) => {
    config.maxRetries = parsePositiveInteger(value, "--retries");
  }],
  ["--timeout", (config, value) => {
    config.timeoutMs = parsePositiveInteger(value, "--timeout");
  }],
  ["--parallel", (config, value) => {
    config.parallelism = parsePositiveInteger(value, "--parallel");
  }],
]);

function validateHandlerArgs(arg: string, nextValue: string | undefined): string {
  if (FLAGS_WITH_VALUE.has(arg)) {
    return assertValue(nextValue, arg);
  }
  return "";
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const raw = argv[i]!;
    const arg = normalizeFlag(raw);
    const handler = HANDLERS.get(arg);

    if (!handler) {
      throw new Error(`unknown flag: ${arg}`);
    }

    const value = FLAGS_WITH_VALUE.has(arg) ? argv[++i] : undefined;
    const resolvedValue = validateHandlerArgs(arg, value);
    handler(config, resolvedValue);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

const DEFAULTS: FlagConfig = {
  verbose: false,
  quiet: false,
  outputPath: null,
  format: "text",
  maxRetries: 3,
  timeoutMs: 30000,
  dryRun: false,
  force: false,
  logLevel: "info",
  configPath: null,
  parallelism: 1,
  color: true,
  strict: false,
};

function defaultFlagConfig(): FlagConfig {
  return { ...DEFAULTS };
}

interface BoolFlag {
  kind: "bool";
  setter: (config: FlagConfig) => void;
}

interface StringFlag {
  kind: "string";
  setter: (config: FlagConfig, value: string) => void;
  validValues?: readonly string[];
  errorPrefix?: string;
}

interface IntFlag {
  kind: "int";
  setter: (config: FlagConfig, value: number) => void;
  errorPrefix: string;
}

type FlagHandler = BoolFlag | StringFlag | IntFlag;

function parseString(
  flagName: string,
  raw: string | undefined,
  validValues?: readonly string[],
  errorPrefix?: string
): string {
  if (raw === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  if (validValues && !validValues.includes(raw)) {
    throw new Error(`${errorPrefix ?? `invalid value for ${flagName}:`} ${raw}`);
  }
  return raw;
}

function parseIntValue(
  flagName: string,
  raw: string | undefined
): number {
  if (raw === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  const value = Number(raw);
  if (!Number.isInteger(value)) {
    throw new Error(`${flagName} must be an integer`);
  }
  return value;
}

const FLAGS: Readonly<Record<string, FlagHandler>> = {
  "--verbose":     { kind: "bool",   setter: (c) => { c.verbose = true;  } },
  "--quiet":       { kind: "bool",   setter: (c) => { c.quiet = true;    } },
  "--dry-run":     { kind: "bool",   setter: (c) => { c.dryRun = true;   } },
  "--force":       { kind: "bool",   setter: (c) => { c.force = true;    } },
  "--no-color":    { kind: "bool",   setter: (c) => { c.color = false;   } },
  "--strict":      { kind: "bool",   setter: (c) => { c.strict = true;   } },
  "--output":      { kind: "string", setter: (c, v) => { c.outputPath = v; }, errorPrefix: "--output requires a path" },
  "--config":      { kind: "string", setter: (c, v) => { c.configPath = v; }, errorPrefix: "--config requires a path" },
  "--format":      { kind: "string", setter: (c, v) => { c.format = v; },   validValues: ["json", "yaml", "text"],  errorPrefix: "unsupported format" },
  "--log-level":   { kind: "string", setter: (c, v) => { c.logLevel = v; }, validValues: ["debug", "info", "warn", "error"], errorPrefix: "unsupported log level" },
  "--retries":     { kind: "int",    setter: (c, v) => { c.maxRetries = v; }, errorPrefix: "--retries must be an integer" },
  "--timeout":     { kind: "int",    setter: (c, v) => { c.timeoutMs = v; },  errorPrefix: "--timeout must be an integer" },
  "--parallel":    { kind: "int",    setter: (c, v) => { c.parallelism = v; }, errorPrefix: "--parallel must be an integer" },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const rawArg = argv[i]!;

    if (!rawArg.startsWith("-")) {
      continue;
    }

    const arg = normalizeFlag(rawArg);
    const handler = FLAGS[arg];

    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    switch (handler.kind) {
      case "bool": {
        handler.setter(config);
        break;
      }
      case "string": {
        const raw = argv[++i];
        const value = parseString(arg, raw, handler.validValues, handler.errorPrefix);
        handler.setter(config, value);
        break;
      }
      case "int": {
        const raw = argv[++i];
        const value = parseIntValue(arg, raw);
        handler.setter(config, value);
        break;
      }
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: ReadonlyMap<string, string> = new Map([
  ["-v", "--verbose"],
  ["-q", "--quiet"],
  ["-f", "--force"],
  ["-o", "--output"],
]);

function normalizeFlag(arg: string): string {
  return ALIASES.get(arg) ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}
type ParseResult = { error?: string };

function parseBoolean(
  _raw: string,
  _next: string | undefined,
  set: (v: boolean) => void
): ParseResult {
  set(true);
  return {};
}

function parsePath(
  raw: string,
  next: string | undefined,
  set: (v: string) => void
): ParseResult {
  if (next === undefined) return { error: `${raw} requires a path` };
  set(next);
  return {};
}

function parseEnum(
  _raw: string,
  next: string | undefined,
  valid: readonly string[],
  set: (v: string) => void
): ParseResult {
  if (next === undefined) return { error: `missing value` };
  if (!valid.includes(next)) return { error: `unsupported value: ${next}` };
  set(next);
  return {};
}

function parseInt(
  raw: string,
  next: string | undefined,
  set: (v: number) => void
): ParseResult {
  if (next === undefined) return { error: `${raw} must be an integer` };
  const value = Number(next);
  if (!Number.isInteger(value)) return { error: `${raw} must be an integer` };
  set(value);
  return {};
}

interface FlagHandler {
  parse(raw: string, next: string | undefined, set: (config: Partial<FlagConfig>) => void): ParseResult;
}

const FLAG_HANDLERS: ReadonlyMap<string, FlagHandler> = new Map([
  ["--verbose", { parse: (_r, _n, s) => parseBoolean(_r, _n, () => s({ verbose: true })) }],
  ["--quiet", { parse: (_r, _n, s) => parseBoolean(_r, _n, () => s({ quiet: true })) }],
  ["--dry-run", { parse: (_r, _n, s) => parseBoolean(_r, _n, () => s({ dryRun: true })) }],
  ["--force", { parse: (_r, _n, s) => parseBoolean(_r, _n, () => s({ force: true })) }],
  ["--strict", { parse: (_r, _n, s) => parseBoolean(_r, _n, () => s({ strict: true })) }],
  ["--no-color", { parse: (_r, _n, s) => parseBoolean(_r, _n, () => s({ color: false })) }],
  ["--output", { parse: (r, n, s) => parsePath(r, n, (v) => s({ outputPath: v })) }],
  ["--config", { parse: (r, n, s) => parsePath(r, n, (v) => s({ configPath: v })) }],
  ["--format", { parse: (_r, n, s) => parseEnum(_r, n, ["json", "yaml", "text"], (v) => s({ format: v })) }],
  ["--log-level", { parse: (_r, n, s) => parseEnum(_r, n, ["debug", "info", "warn", "error"], (v) => s({ logLevel: v })) }],
  ["--retries", { parse: (r, n, s) => parseInt(r, n, (v) => s({ maxRetries: v })) }],
  ["--timeout", { parse: (r, n, s) => parseInt(r, n, (v) => s({ timeoutMs: v })) }],
  ["--parallel", { parse: (r, n, s) => parseInt(r, n, (v) => s({ parallelism: v })) }],
]);

function handleFlag(raw: string, argv: string[], index: number, set: (config: Partial<FlagConfig>) => void): { consumed: number; error?: string } {
  const normalized = normalizeFlag(raw);
  const handler = FLAG_HANDLERS.get(normalized);
  if (!handler) return { consumed: 1, error: `unknown flag: ${raw}` };

  const next = index + 1 < argv.length ? argv[index + 1] : undefined;
  const result = handler.parse(raw, next, set);
  if (result.error) return { consumed: 1, error: result.error };
  return { consumed: 1, error: undefined };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();
  let i = 0;

  while (i < argv.length) {
    const raw = argv[i];
    const { consumed, error } = handleFlag(raw, argv, i, (patch) => {
      Object.assign(config, patch);
    });

    if (error) throw new Error(error);
    i += consumed;
  }

  return config;
}

