export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const gradeThresholds: [number, string][] = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [80, "B-"],
  [77, "C+"],
  [73, "C"],
  [70, "C-"],
  [60, "D"],
];

function computeLetterGrade(score: number): string {
  for (const [threshold, letter] of gradeThresholds) {
    if (score >= threshold) return letter;
  }
  return "F";
}

export function gradeReport(record: StudentRecord): GradeReport {
  let letter = computeLetterGrade(record.score);
  let modifier = "none";

  if (record.absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (record.extraCredit >= 5 && record.score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_THRESHOLDS: [number, string][] = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
  [0,  "F"],
];

export function gradeReport(record: StudentRecord): GradeReport {
  const letter = determineLetter(record.score);
  const modifier = determineModifier(record);

  if (record.absences > 20) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  return { letter, modifier };
}

function determineLetter(score: number): string {
  for (const [threshold, grade] of GRADE_THRESHOLDS) {
    if (score >= threshold) {
      return grade;
    }
  }
  return "F";
}

function determineModifier(record: StudentRecord): string {
  if (record.extraCredit >= 5 && record.score >= 90) {
    return "honors";
  }
  return "none";
}

