interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function isNonNegativeInteger(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 0;
}

function isPositiveInteger(value: unknown): value is number {
  return Number.isInteger(value) && (value as number) >= 1;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function maybeStock(item: string, stock: Record<string, number>): number {
  return stock[item] === undefined ? 0 : stock[item];
}

function drainQueue(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = maybeStock(want.item, stock);
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position--;
    }
  }
}

function makeError(index: number, message: string): FulfillmentResult {
  return { ok: false, error: `event ${index}: ${message}` };
}

function validateOrderId(
  event: Record<string, unknown>,
  index: number
): FulfillmentResult | null {
  if (!isNonEmptyString(event.id)) {
    return makeError(index, "bad id");
  }
  return null;
}

type OrderIdResult = { id: string } | null;

function validateOrderIdOrReject(
  event: Record<string, unknown>,
  index: number
): FulfillmentResult | string {
  if (!isNonEmptyString(event.id)) {
    return makeError(index, "bad id");
  }
  return event.id as string;
}

function handleBackorderedCancel(
  id: string,
  orders: Record<string, string>,
  queue: string[],
  pendingWants: Record<string, Want>
): void {
  const pos = queue.indexOf(id);
  if (pos !== -1) {
    queue.splice(pos, 1);
  }
  delete pendingWants[id];
  orders[id] = "cancelled";
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInteger(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: `event ${index}: malformed` };
    }

    switch (event.type) {
      case "order": {
        if (!isNonEmptyString(event.id)) return makeError(index, "bad id");
        const id = event.id as string;
        if (orders[id] !== undefined) return makeError(index, "duplicate order");

        if (!isNonEmptyString(event.item)) return makeError(index, "bad item");
        const item = event.item as string;

        if (!isPositiveInteger(event.qty)) return makeError(index, "bad qty");
        const qty = event.qty as number;

        const available = maybeStock(item, stock);
        if (available >= qty) {
          stock[item] = available - qty;
          reserved[id] = { item, qty };
          orders[id] = "reserved";
        } else {
          queue.push(id);
          pendingWants[id] = { item, qty };
          orders[id] = "backordered";
        }
        break;
      }

      case "cancel": {
        const idOrErr = validateOrderIdOrReject(event, index);
        if (typeof idOrErr === "string") {
          const id = idOrErr;
          if (reserved[id] !== undefined) {
            const holding = reserved[id];
            stock[holding.item] = maybeStock(holding.item, stock) + holding.qty;
            delete reserved[id];
            orders[id] = "cancelled";
            drainQueue(stock, reserved, pendingWants, queue, orders);
          } else if (orders[id] === "backordered") {
            handleBackorderedCancel(id, orders, queue, pendingWants);
          } else {
            rejected++;
          }
        } else {
          return idOrErr;
        }
        break;
      }

      case "ship": {
        const result2 = validateOrderId(event, index);
        if (result2) return result2;
        const id = event.id as string;

        if (event.qty !== undefined && (!isPositiveInteger(event.qty))) {
          return makeError(index, "bad qty");
        }
        const maybeQty = event.qty === undefined ? undefined : (event.qty as number);

        if (reserved[id] === undefined) {
          rejected++;
        } else if (maybeQty === undefined || maybeQty === reserved[id].qty) {
          delete reserved[id];
          orders[id] = "shipped";
        } else if (maybeQty! < reserved[id].qty) {
          reserved[id].qty -= maybeQty!;
          orders[id] = "partial";
        } else {
          rejected++;
        }
        break;
      }

      case "restock": {
        if (!isNonEmptyString(event.item)) return makeError(index, "bad item");
        const item = event.item as string;

        if (!isPositiveInteger(event.qty)) return makeError(index, "bad qty");
        const qty = event.qty as number;

        stock[item] = maybeStock(item, stock) + qty;
        drainQueue(stock, reserved, pendingWants, queue, orders);
        break;
      }

      case "expire": {
        const result3 = validateOrderId(event, index);
        if (result3) return result3;
        const id = event.id as string;

        if (reserved[id] !== undefined) {
          const holding = reserved[id];
          stock[holding.item] = maybeStock(holding.item, stock) + holding.qty;
          delete reserved[id];
          orders[id] = "expired";
          drainQueue(stock, reserved, pendingWants, queue, orders);
        } else {
          rejected++;
        }
        break;
      }

      default:
        return makeError(index, "bad type");
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

