  pendingWants: Record<string, Want>;
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  orders: Record<string, string>;
}): void {
  const { queue, pendingWants, stock, reserved, orders } = state;
  for (let i = 0; i < queue.length; i++) {
    const pendingId = queue[i];
    const want = pendingWants[pendingId];
    const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(i, 1);
      i--;
    }
  }
}

function dispatchOrder(
  _index: number,
  event: Record<string, unknown>,
  ctx: string,
  state: {
    orders: Record<string, string>;
    reserved: Record<string, Want>;
    pendingWants: Record<string, Want>;
    queue: string[];
    rejected: number;
    stock: Record<string, number>;
  }
): string | null {
  const { orders, reserved, pendingWants, queue, stock } = state;
  if (!isNonEmptyString(event.id)) return `${ctx}bad id`;
  const id = event.id;
  if (orders[id] !== undefined) return `${ctx}duplicate order`;
  if (!isNonEmptyString(event.item)) return `${ctx}bad item`;
  const item = event.item;
  if (!isPositiveInteger(event.qty)) return `${ctx}bad qty`;
  const qty = event.qty;
  const available = stock[item] === undefined ? 0 : stock[item];
  if (available >= qty) {
    stock[item] = available - qty;
    reserved[id] = { item, qty };
    orders[id] = "reserved";
  } else {
    queue.push(id);
    pendingWants[id] = { item, qty };
    orders[id] = "backordered";
  }
  return null;
}

function dispatchCancel(
  _index: number,
  event: Record<string, unknown>,
  ctx: string,
  state: {
    orders: Record<string, string>;
    reserved: Record<string, Want>;
    pendingWants: Record<string, Want>;
    queue: string[];
    rejected: number;
    stock: Record<string, number>;
  }
): string | null {
  const { orders, reserved, pendingWants, queue, rejected, stock } = state;
  if (!isNonEmptyString(event.id)) return `${ctx}bad id`;
  const id = event.id;
  if (reserved[id] !== undefined) {
    const holding = reserved[id];
    const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
    stock[holding.item] = back + holding.qty;
    delete reserved[id];
    orders[id] = "cancelled";
    fillQueue(state);
  } else if (orders[id] === "backordered") {
    const idx = queue.indexOf(id);
    if (idx !== -1) {
      queue.splice(idx, 1);
      delete pendingWants[id];
      orders[id] = "cancelled";
    }
  } else {
    state.rejected += 1;
  }
  return null;
}

function dispatchShip(
  _index: number,
  event: Record<string, unknown>,
  ctx: string,
  state: {
    orders: Record<string, string>;
    reserved: Record<string, Want>;
    pendingWants: Record<string, Want>;
    queue: string[];
    rejected: number;
    stock: Record<string, number>;
  }
): string | null {
  const { orders, reserved, rejected } = state;
  if (!isNonEmptyString(event.id)) return `${ctx}bad id`;
  const id = event.id;
  if (event.qty !== undefined && !isPositiveInteger(event.qty)) {
    return `${ctx}bad qty`;
  }
  const reservation = reserved[id];
  if (reservation === undefined) {
    state.rejected += 1;
  } else {
    const shippedQty =
      event.qty === undefined ? reservation.qty : (event.qty as number);
    if (shippedQty === reservation.qty) {
      delete reserved[id];
      orders[id] = "shipped";
    } else if (shippedQty < reservation.qty) {
      reservation.qty -= shippedQty;
      orders[id] = "partial";
    } else {
      state.rejected += 1;
    }
  }
  return null;
}

function dispatchRestock(
  _index: number,
  event: Record<string, unknown>,
  ctx: string,
  state: {
    orders: Record<string, string>;
    reserved: Record<string, Want>;
    pendingWants: Record<string, Want>;
    queue: string[];
    rejected: number;
    stock: Record<string, number>;
  }
): string | null {
  const { stock } = state;
  if (!isNonEmptyString(event.item)) return `${ctx}bad item`;
  const item = event.item;
  if (!isPositiveInteger(event.qty)) return `${ctx}bad qty`;
  const qty = event.qty;
  const held = stock[item] === undefined ? 0 : stock[item];
  stock[item] = held + qty;
  fillQueue(state);
  return null;
}

function dispatchExpire(
  _index: number,
  event: Record<string, unknown>,
  ctx: string,
  state: {
    orders: Record<string, string>;
    reserved: Record<string, Want>;
    pendingWants: Record<string, Want>;
    queue: string[];
    rejected: number;
    stock: Record<string, number>;
  }
): string | null {
  const { reserved, rejected, stock, orders } = state;
  if (!isNonEmptyString(event.id)) return `${ctx}bad id`;
  const id = event.id;
  if (reserved[id] !== undefined) {
    const holding = reserved[id];
    const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
    stock[holding.item] = back + holding.qty;
    delete reserved[id];
    orders[id] = "expired";
    fillQueue(state);
  } else {
    state.rejected += 1;
  }
  return null;
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = stock[event.item] === undefined ? 0 : stock[event.item];
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        for (let position = 0; position < queue.length; position++) {
          const pendingId = queue[position];
          const want = pendingWants[pendingId];
          const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
          if (onHand >= want.qty) {
            stock[want.item] = onHand - want.qty;
            reserved[pendingId] = { item: want.item, qty: want.qty };
            orders[pendingId] = "reserved";
            delete pendingWants[pendingId];
            queue.splice(position, 1);
            position = position - 1;
          }
        }
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const held = stock[event.item] === undefined ? 0 : stock[event.item];
      stock[event.item] = held + (event.qty as number);
      for (let position = 0; position < queue.length; position++) {
        const pendingId = queue[position];
        const want = pendingWants[pendingId];
        const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
        if (onHand >= want.qty) {
          stock[want.item] = onHand - want.qty;
          reserved[pendingId] = { item: want.item, qty: want.qty };
          orders[pendingId] = "reserved";
          delete pendingWants[pendingId];
          queue.splice(position, 1);
          position = position - 1;
        }
      }
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        for (let position = 0; position < queue.length; position++) {
          const pendingId = queue[position];
          const want = pendingWants[pendingId];
          const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
          if (onHand >= want.qty) {
            stock[want.item] = onHand - want.qty;
            reserved[pendingId] = { item: want.item, qty: want.qty };
            orders[pendingId] = "reserved";
            delete pendingWants[pendingId];
            queue.splice(position, 1);
            position = position - 1;
          }
        }
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type StockMap = Record<string, number>;
type ReservedMap = Record<string, Want>;
type PendingWantsMap = Record<string, Want>;
type OrdersMap = Record<string, string>;

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

function getStock(stock: StockMap, item: string): number {
  return stock[item] ?? 0;
}

function tryFulfillFromQueue(
  id: string,
  want: Want,
  stock: StockMap,
  reserved: ReservedMap,
  pendingWants: PendingWantsMap,
  queue: string[],
  orders: OrdersMap
): boolean {
  if (getStock(stock, want.item) >= want.qty) {
    stock[want.item] = getStock(stock, want.item) - want.qty;
    reserved[id] = want;
    orders[id] = "reserved";
    delete pendingWants[id];
    return true;
  }
  return false;
}

function processQueue(
  stock: StockMap,
  reserved: ReservedMap,
  pendingWants: PendingWantsMap,
  queue: string[],
  orders: OrdersMap
): void {
  let position = 0;
  while (position < queue.length) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    if (tryFulfillFromQueue(pendingId, want, stock, reserved, pendingWants, queue, orders)) {
      queue.splice(position, 1);
    } else {
      position++;
    }
  }
}

type EventContext = {
  stock: StockMap;
  reserved: ReservedMap;
  pendingWants: PendingWantsMap;
  queue: string[];
  orders: OrdersMap;
  rejected: number;
};

function handleOrder(
  index: number,
  event: Record<string, unknown>,
  ctx: EventContext
): FulfillmentResult | void {
  const id = event.id;
  const item = event.item;
  const qty = event.qty;

  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: `event ${index}: bad id` };
  }
  if (ctx.orders[id] !== undefined) {
    return { ok: false, error: `event ${index}: duplicate order` };
  }
  if (typeof item !== "string" || item.length === 0) {
    return { ok: false, error: `event ${index}: bad item` };
  }
  if (!isPositiveInteger(qty)) {
    return { ok: false, error: `event ${index}: bad qty` };
  }

  if (getStock(ctx.stock, item) >= qty) {
    ctx.stock[item] = getStock(ctx.stock, item) - qty;
    ctx.reserved[id] = { item, qty };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty };
    ctx.orders[id] = "backordered";
  }
}

function handleCancel(
  index: number,
  event: Record<string, unknown>,
  ctx: EventContext
): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: `event ${index}: bad id` };
  }

  if (ctx.reserved[id] !== undefined) {
    const { item, qty } = ctx.reserved[id];
    ctx.stock[item] = getStock(ctx.stock, item) + qty;
    delete ctx.reserved[id];
    ctx.orders[id] = "cancelled";
    processQueue(ctx.stock, ctx.reserved, ctx.pendingWants, ctx.queue, ctx.orders);
  } else if (ctx.orders[id] === "backordered") {
    const idx = ctx.queue.indexOf(id);
    if (idx !== -1) {
      ctx.queue.splice(idx, 1);
      delete ctx.pendingWants[id];
    }
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected++;
  }
}

function applyShip(
  reservedEntry: Want,
  partialQty: number | undefined
): { status: "shipped" | "partial"; remaining?: number } | { status: "reject" } {
  if (partialQty === undefined || partialQty === reservedEntry.qty) {
    return { status: "shipped" };
  }
  if (partialQty < reservedEntry.qty) {
    return { status: "partial", remaining: reservedEntry.qty - partialQty };
  }
  return { status: "reject" };
}

function handleShip(
  index: number,
  event: Record<string, unknown>,
  ctx: EventContext
): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: `event ${index}: bad id` };
  }

  const partialQty = event.qty;
  if (partialQty !== undefined && !isPositiveInteger(partialQty)) {
    return { ok: false, error: `event ${index}: bad qty` };
  }

  const entry = ctx.reserved[id];
  if (entry === undefined) {
    ctx.rejected++;
  } else {
    const result = applyShip(entry, partialQty);
    if (result.status === "shipped") {
      delete ctx.reserved[id];
      ctx.orders[id] = "shipped";
    } else if (result.status === "partial") {
      ctx.reserved[id].qty = result.remaining!;
      ctx.orders[id] = "partial";
    } else {
      ctx.rejected++;
    }
  }
}

function handleRestock(
  index: number,
  event: Record<string, unknown>,
  ctx: EventContext
): FulfillmentResult | void {
  const item = event.item;
  const qty = event.qty;

  if (typeof item !== "string" || item.length === 0) {
    return { ok: false, error: `event ${index}: bad item` };
  }
  if (!isPositiveInteger(qty)) {
    return { ok: false, error: `event ${index}: bad qty` };
  }

  ctx.stock[item] = getStock(ctx.stock, item) + qty;
  processQueue(ctx.stock, ctx.reserved, ctx.pendingWants, ctx.queue, ctx.orders);
}

function handleExpire(
  index: number,
  event: Record<string, unknown>,
  ctx: EventContext
): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: `event ${index}: bad id` };
  }

  if (ctx.reserved[id] !== undefined) {
    const { item, qty } = ctx.reserved[id];
    ctx.stock[item] = getStock(ctx.stock, item) + qty;
    delete ctx.reserved[id];
    ctx.orders[id] = "expired";
    processQueue(ctx.stock, ctx.reserved, ctx.pendingWants, ctx.queue, ctx.orders);
  } else {
    ctx.rejected++;
  }
}

type EventType = "order" | "cancel" | "ship" | "restock" | "expire";

const EVENT_TYPE_MAP: Record<EventType, (index: number, event: Record<string, unknown>, ctx: EventContext) => FulfillmentResult | void> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function isEventType(value: unknown): value is EventType {
  return typeof value === "string" && value in EVENT_TYPE_MAP;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;

  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: StockMap = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const value = rawStock[item];
    if (!isNonNegativeInteger(value)) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = value;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: OrdersMap = {};
  const reserved: ReservedMap = {};
  const pendingWants: PendingWantsMap = {};
  const queue: string[] = [];
  let rejected = 0;

  const result = processEventLoop(input.events, { stock, reserved, pendingWants, queue, orders, rejected });
  if (result.error !== undefined) {
    return { ok: false, error: result.error };
  }

  return {
    ok: true,
    orders: result.ctx.orders,
    stock: result.ctx.stock,
    queue: result.ctx.queue,
    rejected: result.ctx.rejected,
    report: buildReport(result.ctx.orders, result.ctx.rejected),
  };
}

function processEventLoop(
  events: unknown[],
  initialCtx: EventContext
): { ctx: EventContext; error?: string } {
  let ctx = { ...initialCtx };

  for (let index = 0; index < events.length; index++) {
    const event = events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ctx, error: `event ${index}: malformed` };
    }

    if (!isEventType(event.type)) {
      return { ctx, error: `event ${index}: bad type` };
    }

    const err = EVENT_TYPE_MAP[event.type](index, event, ctx);
    if (err !== undefined) {
      return { ctx, error: err.error };
    }
  }

  return { ctx };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"] as const;

function statusCounts(orders: OrdersMap): Record<string, number> {
  const counts: Record<string, number> = { reserved: 0, backordered: 0, shipped: 0, partial: 0, cancelled: 0, expired: 0 };
  for (const status of Object.values(orders)) {
    counts[status]++;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    if (event.type === "order") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = stock[event.item] === undefined ? 0 : stock[event.item];
      if (available >= (event.qty as number)) {
        stock[event.item] = available - (event.qty as number);
        reserved[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty: event.qty as number };
        orders[event.id] = "backordered";
      }
    } else if (event.type === "cancel") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        for (let position = 0; position < queue.length; position++) {
          const pendingId = queue[position];
          const want = pendingWants[pendingId];
          const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
          if (onHand >= want.qty) {
            stock[want.item] = onHand - want.qty;
            reserved[pendingId] = { item: want.item, qty: want.qty };
            orders[pendingId] = "reserved";
            delete pendingWants[pendingId];
            queue.splice(position, 1);
            position = position - 1;
          }
        }
      } else if (orders[event.id] === "backordered") {
        queue.splice(queue.indexOf(event.id), 1);
        delete pendingWants[event.id];
        orders[event.id] = "cancelled";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "ship") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      if (reserved[event.id] === undefined) {
        rejected = rejected + 1;
      } else if (event.qty === undefined || (event.qty as number) === reserved[event.id].qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if ((event.qty as number) < reserved[event.id].qty) {
        reserved[event.id].qty = reserved[event.id].qty - (event.qty as number);
        orders[event.id] = "partial";
      } else {
        rejected = rejected + 1;
      }
    } else if (event.type === "restock") {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      if (!Number.isInteger(event.qty) || (event.qty as number) < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const held = stock[event.item] === undefined ? 0 : stock[event.item];
      stock[event.item] = held + (event.qty as number);
      for (let position = 0; position < queue.length; position++) {
        const pendingId = queue[position];
        const want = pendingWants[pendingId];
        const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
        if (onHand >= want.qty) {
          stock[want.item] = onHand - want.qty;
          reserved[pendingId] = { item: want.item, qty: want.qty };
          orders[pendingId] = "reserved";
          delete pendingWants[pendingId];
          queue.splice(position, 1);
          position = position - 1;
        }
      }
    } else if (event.type === "expire") {
      if (typeof event.id !== "string" || event.id.length === 0) {
        return { ok: false, error: "event " + index + ": bad id" };
      }
      if (reserved[event.id] !== undefined) {
        const holding = reserved[event.id];
        const back = stock[holding.item] === undefined ? 0 : stock[holding.item];
        stock[holding.item] = back + holding.qty;
        delete reserved[event.id];
        orders[event.id] = "expired";
        for (let position = 0; position < queue.length; position++) {
          const pendingId = queue[position];
          const want = pendingWants[pendingId];
          const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
          if (onHand >= want.qty) {
            stock[want.item] = onHand - want.qty;
            reserved[pendingId] = { item: want.item, qty: want.qty };
            orders[pendingId] = "reserved";
            delete pendingWants[pendingId];
            queue.splice(position, 1);
            position = position - 1;
          }
        }
      } else {
        rejected = rejected + 1;
      }
    } else {
      return { ok: false, error: "event " + index + ": bad type" };
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

