export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  if (order.id.length === 0) {
    errors.push("order id is required");
  }

  if (order.customerId.length === 0) {
    errors.push("customer id is required");
  }

  if (order.items.length === 0) {
    errors.push("order must contain at least one item");
  } else {
    for (const item of order.items) {
      if (item.quantity <= 0 || item.quantity === 0) {
        errors.push(`item ${item.sku} has a non-positive quantity`);
      }
    }
  }

  if (order.shippingAddress === null) {
    errors.push("shipping address is required");
  } else if (order.shippingAddress.postalCode.length === 0 || order.shippingAddress.postalCode.trim().length === 0) {
    errors.push("shipping postal code is required");
  }

  if (order.billingAddress === null) {
    errors.push("billing address is required");
  }

  if (order.totalCents <= 0) {
    errors.push("order total must be positive");
  }

  if (order.currency !== "USD" && order.currency !== "EUR") {
    errors.push(`unsupported currency: ${order.currency}`);
  }

  return { valid: errors.length === 0, errors };
}

files.process_events.ts:
interface Want {
  item: string;
  qty: number;
}

function isStringField(val: unknown): val is string {
  return typeof val === "string";
}

function drainQueue(
  queue: string[],
  pendingWants: Record<string, Want>,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
): void {
  for (let i = 0; i < queue.length; i++) {
    const pendingId = queue[i];
    const want = pendingWants[pendingId];
    if (want && (stock[want.item] ?? 0) >= want.qty) {
      stock[want.item]! -= want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(i, 1);
      i--;
    }
  }
}

function orderEvent(
  orderId: string,
  item: string,
  qty: number,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
  pendingWants: Record<string, Want>,
): void {
  const available = stock[item] ?? 0;
  if (available >= qty) {
    stock[item] = available - qty;
    reserved[orderId] = { item, qty };
    orders[orderId] = "reserved";
  } else {
    queue.push(orderId);
    pendingWants[orderId] = { item, qty };
    orders[orderId] = "backordered";
  }
}

function cancelEvent(
  orderId: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
  pendingWants: Record<string, Want>,
  rejected: number[],
): void {
  if (reserved[orderId] !== undefined) {
    const holding = reserved[orderId];
    stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
    delete reserved[orderId];
    orders[orderId] = "cancelled";
    drainQueue(queue, pendingWants, stock, reserved, orders);
  } else if (orders[orderId] === "backordered") {
    const idx = queue.indexOf(orderId);
    if (idx !== -1) queue.splice(idx, 1);
    delete pendingWants[orderId];
    orders[orderId] = "cancelled";
  } else {
    rejected[0]++;
  }
}

function shipEvent(
  orderId: string,
  shipQty: unknown,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  rejected: number[],
): void {
  const res = reserved[orderId];
  if (res === undefined) {
    rejected[0]++;
  } else {
    const delivered = shipQty === undefined ? res.qty : (shipQty as number);
    if (delivered === res.qty) {
      delete reserved[orderId];
      orders[orderId] = "shipped";
    } else if (delivered < res.qty) {
      res.qty = res.qty - delivered;
      orders[orderId] = "partial";
    } else {
      rejected[0]++;
    }
  }
}

function restockEvent(
  item: string,
  qty: number,
  stock: Record<string, number>,
  queue: string[],
  pendingWants: Record<string, Want>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
): void {
  stock[item] = (stock[item] ?? 0) + qty;
  drainQueue(queue, pendingWants, stock, reserved, orders);
}

function expireEvent(
  orderId: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
  pendingWants: Record<string, Want>,
  rejected: number[],
): void {
  if (reserved[orderId] !== undefined) {
    const holding = reserved[orderId];
    stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
    delete reserved[orderId];
    orders[orderId] = "expired";
    drainQueue(queue, pendingWants, stock, reserved, orders);
  } else {
    rejected[0]++;
  }
}

const EVENT_HANDLERS: Record<string, (
  event: Record<string, unknown>,
  index: number,
  ctx: {
    stock: Record<string, number>;
    reserved: Record<string, Want>;
    orders: Record<string, string>;
    queue: string[];
    pendingWants: Record<string, Want>;
    rejected: number[];
  }
) => { ok: false; error: string } | undefined> = {
  order(event, index, ctx) {
    if (!isStringField(event.id) || event.id.length === 0) {
      return { ok: false, error: `event ${index}: bad id` };
    }
    const orderId = event.id;
    if (ctx.orders[orderId] !== undefined) {
      return { ok: false, error: `event ${index}: duplicate order` };
    }
    if (!isStringField(event.item) || event.item.length === 0) {
      return { ok: false, error: `event ${index}: bad item` };
    }
    const qty = event.qty as number;
    if (!Number.isInteger(qty) || qty < 1) {
      return { ok: false, error: `event ${index}: bad qty` };
    }
    orderEvent(orderId, event.item, qty, ctx.stock, ctx.reserved, ctx.orders, ctx.queue, ctx.pendingWants);
  },
  cancel(event, index, ctx) {
    if (!isStringField(event.id) || event.id.length === 0) {
      return { ok: false, error: `event ${index}: bad id` };
    }
    cancelEvent(event.id, ctx.stock, ctx.reserved, ctx.orders, ctx.queue, ctx.pendingWants, ctx.rejected);
  },
  ship(event, index, ctx) {
    if (!isStringField(event.id) || event.id.length === 0) {
      return { ok: false, error: `event ${index}: bad id` };
    }
    const shipQty = event.qty;
    if (shipQty !== undefined && (!Number.isInteger(shipQty) || (shipQty as number) < 1)) {
      return { ok: false, error: `event ${index}: bad qty` };
    }
    shipEvent(event.id, shipQty, ctx.reserved, ctx.orders, ctx.rejected);
  },
  restock(event, index, ctx) {
    if (!isStringField(event.item) || event.item.length === 0) {
      return { ok: false, error: `event ${index}: bad item` };
    }
    const qty = event.qty as number;
    if (!Number.isInteger(qty) || qty < 1) {
      return { ok: false, error: `event ${index}: bad qty` };
    }
    restockEvent(event.item, qty, ctx.stock, ctx.queue, ctx.pendingWants, ctx.reserved, ctx.orders);
  },
  expire(event, index, ctx) {
    if (!isStringField(event.id) || event.id.length === 0) {
      return { ok: false, error: `event ${index}: bad id` };
    }
    expireEvent(event.id, ctx.stock, ctx.reserved, ctx.orders, ctx.queue, ctx.pendingWants, ctx.rejected);
  },
};

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function parseStock(raw: Record<string, unknown>): Record<string, number> | { ok: false; error: string } {
  const stock: Record<string, number> = {};
  const rawStock = raw.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const val = rawStock[item];
    if (!Number.isInteger(val) || (val as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = val as number;
  }
  return stock;
}

function validateRaw(raw: unknown): { ok: false; error: string } | Record<string, unknown> {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }
  return input;
}

function processEvents(raw: unknown): FulfillmentResult {
  const validation = validateRaw(raw);
  if (!validation.ok) return validation;
  const input = validation;

  const stockResult = parseStock(input);
  if (!stockResult.ok) return stockResult;
  const stock = stockResult;

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  const rejected: number[] = [0];

  const ctx = { stock, reserved, orders, queue, pendingWants, rejected };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: `event ${index}: malformed` };
    }

    const eventType = event.type as string;
    const handler = EVENT_HANDLERS[eventType];
    if (handler === undefined) {
      return { ok: false, error: `event ${index}: bad type` };
    }
    const result = handler(event, index, ctx);
    if (result !== undefined) return result;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected: rejected[0],
    report: buildReport(orders, rejected[0]),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

interface OrderEvent {
  type: "order";
  id: string;
  item: string;
  qty: number;
}

interface CancelEvent {
  type: "cancel";
  id: string;
}

interface ShipEvent {
  type: "ship";
  id: string;
  qty?: number;
}

interface RestockEvent {
  type: "restock";
  item: string;
  qty: number;
}

interface ExpireEvent {
  type: "expire";
  id: string;
}

type ParsedEvent = OrderEvent | CancelEvent | ShipEvent | RestockEvent | ExpireEvent;

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const val = rawStock[item];
    if (typeof val !== "number" || !Number.isInteger(val) || val < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = val;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const fail = (idx: number, msg: string) => ({ ok: false, error: `event ${idx}: ${msg}` } as FulfillmentResult);

  const reserve = (id: string, want: Want) => {
    stock[want.item] = (stock[want.item] ?? 0) - want.qty;
    reserved[id] = { item: want.item, qty: want.qty };
    orders[id] = "reserved";
    delete pendingWants[id];
  };

  const backorder = (id: string, want: Want) => {
    queue.push(id);
    pendingWants[id] = { item: want.item, qty: want.qty };
    orders[id] = "backordered";
  };

  const drainQueue = () => {
    for (let i = 0; i < queue.length; i++) {
      const pendingId = queue[i];
      const want = pendingWants[pendingId];
      const onHand = stock[want.item] ?? 0;
      if (onHand >= want.qty) {
        stock[want.item] = onHand - want.qty;
        reserved[pendingId] = { item: want.item, qty: want.qty };
        orders[pendingId] = "reserved";
        delete pendingWants[pendingId];
        queue.splice(i, 1);
      } else {
        break;
      }
    }
  };

  for (let index = 0; index < input.events.length; index++) {
    const raw = input.events[index];
    if (typeof raw !== "object" || raw === null) return fail(index, "malformed");

    const evt = parseEvent(raw, index);
    if (evt === null) return fail(index, "malformed");

    switch (evt.type) {
      case "order": {
        if (orders[evt.id] !== undefined) return fail(index, "duplicate order");
        const available = stock[evt.item] ?? 0;
        if (available >= evt.qty) {
          reserve(evt.id, evt);
        } else {
          backorder(evt.id, evt);
        }
        break;
      }
      case "cancel": {
        if (reserved[evt.id] !== undefined) {
          const holding = reserved[evt.id];
          stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
          delete reserved[evt.id];
          orders[evt.id] = "cancelled";
          drainQueue();
        } else if (orders[evt.id] === "backordered") {
          const pos = queue.indexOf(evt.id);
          if (pos !== -1) {
            queue.splice(pos, 1);
            delete pendingWants[evt.id];
          }
          orders[evt.id] = "cancelled";
        } else {
          rejected++;
        }
        break;
      }
      case "ship": {
        if (reserved[evt.id] === undefined) {
          rejected++;
        } else {
          const full = reserved[evt.id];
          const sent = evt.qty ?? full.qty;
          if (sent === full.qty) {
            delete reserved[evt.id];
            orders[evt.id] = "shipped";
          } else if (sent < full.qty) {
            full.qty -= sent;
            orders[evt.id] = "partial";
          } else {
            rejected++;
          }
        }
        break;
      }
      case "restock": {
        stock[evt.item] = (stock[evt.item] ?? 0) + evt.qty;
        drainQueue();
        break;
      }
      case "expire": {
        if (reserved[evt.id] !== undefined) {
          const holding = reserved[evt.id];
          stock[holding.item] = (stock[holding.item] ?? 0) + holding.qty;
          delete reserved[evt.id];
          orders[evt.id] = "expired";
          drainQueue();
        } else {
          rejected++;
        }
        break;
      }
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

function parseEvent(raw: Record<string, unknown>, index: number): ParsedEvent | null {
  const type = raw.type;
  if (typeof type !== "string") return null;

  switch (type) {
    case "order": {
      const id = raw.id;
      if (typeof id !== "string" || id.length === 0) return null;
      const item = raw.item;
      if (typeof item !== "string" || item.length === 0) return null;
      const qty = raw.qty;
      if (typeof qty !== "number" || !Number.isInteger(qty) || qty < 1) return null;
      return { type, id, item, qty };
    }
    case "cancel": {
      const id = raw.id;
      if (typeof id !== "string" || id.length === 0) return null;
      return { type, id };
    }
    case "ship": {
      const id = raw.id;
      if (typeof id !== "string" || id.length === 0) return null;
      const qty = raw.qty;
      if (qty !== undefined && (typeof qty !== "number" || !Number.isInteger(qty) || qty < 1)) return null;
      return { type, id, qty };
    }
    case "restock": {
      const item = raw.item;
      if (typeof item !== "string" || item.length === 0) return null;
      const qty = raw.qty;
      if (typeof qty !== "number" || !Number.isInteger(qty) || qty < 1) return null;
      return { type, item, qty };
    }
    case "expire": {
      const id = raw.id;
      if (typeof id !== "string" || id.length === 0) return null;
      return { type, id };
    }
    default:
      return null;
  }
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

