  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

function isNonBlank(value: string): boolean {
  return value.length > 0 && value.trim().length > 0;
}

function validateAddress(address: Address | null, label: string): string[] {
  if (address === null) return [`${label} address is required`];
  if (!isNonBlank(address.postalCode)) return [`${label} postal code is required`];
  return [];
}

function validateItems(items: OrderItem[]): string[] {
  if (items.length === 0) return ["order must contain at least one item"];
  const errors: string[] = [];
  for (const item of items) {
    if (item.quantity <= 0) {
      errors.push(`item ${item.sku} has a non-positive quantity`);
    }
  }
  return errors;
}

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  if (!isNonBlank(order.id)) errors.push("order id is required");
  if (!isNonBlank(order.customerId)) errors.push("customer id is required");
  errors.push(...validateItems(order.items));
  errors.push(...validateAddress(order.shippingAddress, "shipping"));
  errors.push(...validateAddress(order.billingAddress, "billing"));

  if (order.totalCents <= 0) errors.push("order total must be positive");
  if (order.currency !== "USD" && order.currency !== "EUR") {
    errors.push(`unsupported currency: ${order.currency}`);
  }

  return { valid: errors.length === 0, errors };
}

