import { validateOrder, Order } from "./validate_order";

const base: Order = {
  id: "123",
  customerId: "cust1",
  items: [{ sku: "A", quantity: 1, unitPrice: 10 }],
  shippingAddress: { line1: "1 St", city: "NYC", postalCode: "10001", country: "US" },
  billingAddress: { line1: "1 St", city: "NYC", postalCode: "10001", country: "US" },
  totalCents: 1000,
  currency: "USD"
};

function test(name: string, order: Order, expectValid: boolean, expectErrors: string[]) {
  const result = validateOrder(order);
  console.assert(result.valid === expectValid, `${name}: expected valid=${expectValid} but got ${result.valid} (${JSON.stringify(result.errors)})`);
  for (const exp of expectErrors) {
    console.assert(result.errors.includes(exp), `${name}: expected error "${exp}" not found in ${JSON.stringify(result.errors)}`);
  }
}

// Valid order
test("valid", base, true, []);

// Empty id
test("empty id", { ...base, id: "" }, false, ["order id is required"]);

// Empty customerId
test("empty customerId", { ...base, customerId: "" }, false, ["customer id is required"]);

// No items
test("no items", { ...base, items: [] }, false, ["order must contain at least one item"]);

// Zero quantity (originally buggy: <= 0 || === 0)
test("zero quantity", { ...base, items: [{ sku: "A", quantity: 0, unitPrice: 10 }] }, false, ["item A has a non-positive quantity"]);

// Shipping null
test("shipping null", { ...base, shippingAddress: null }, false, ["shipping address is required"]);

// Shipping blank postal code (originally buggy: length===0 || trim().length===0)
test("shipping blank postal", { ...base, shippingAddress: { line1: "1", city: "NYC", postalCode: "  ", country: "US" } }, false, ["shipping postal code is required"]);

