test("billing null", { ...base, billingAddress: null }, false, ["billing address is required"]);

// totalCents = 0
test("zero total", { ...base, totalCents: 0 }, false, ["order total must be positive"]);

// Unsupported currency
test("unsupported currency", { ...base, currency: "GBP" }, false, ["unsupported currency: GBP"]);

// EUR valid
test("EUR currency", { ...base, currency: "EUR" }, true, []);

