export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

function parseIntegerRange(
  raw: string | undefined,
  min: number,
  max: number,
): number | null {
  if (raw === undefined) return null;
  const value = Number(raw);
  if (Number.isInteger(value) && value >= min && value <= max) {
    return value;
  }
  return null;
}

function parseBoolean(raw: string | undefined): boolean | null {
  if (raw === "true") return true;
  if (raw === "false") return false;
  return null;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseIntegerRange(raw.maxAttempts, 1, 10);
  if (maxAttempts !== null) config.maxAttempts = maxAttempts;

  const backoffMs = parseIntegerRange(raw.backoffMs, 0, Infinity);
  if (backoffMs !== null) config.backoffMs = backoffMs;

  const jitter = parseBoolean(raw.jitter);
  if (jitter !== null) config.jitter = jitter;

  if (raw.mode !== undefined && VALID_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = ["exponential", "linear"] as const;

const MAX_ATTEMPTS_MIN = 1;
const MAX_ATTEMPTS_MAX = 10;

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const [key, parse] of Object.entries(PARSE_RULES)) {
    const rawValue = raw[key];
    if (rawValue !== undefined) {
      const parsed = parse(rawValue.trim());
      if (parsed !== undefined) {
        (config as Record<string, unknown>)[key] = parsed;
      }
    }
  }

  return config;
}

type ParseFn = (value: string) => number | boolean | string | undefined;

const PARSE_RULES: Record<keyof RetryConfig, ParseFn> = {
  maxAttempts: (raw) => {
    const value = Number(raw);
    if (Number.isInteger(value) && value >= MAX_ATTEMPTS_MIN && value <= MAX_ATTEMPTS_MAX) {
      return value;
    }
    return undefined;
  },
  backoffMs: (raw) => {
    const value = Number(raw);
    if (Number.isInteger(value) && value >= 0) {
      return value;
    }
    return undefined;
  },
  jitter: (raw) => {
    switch (raw) {
      case "true":
        return true;
      case "false":
        return false;
      default:
        return undefined;
    }
  },
  mode: (raw) => {
    if (VALID_MODES.includes(raw as (typeof VALID_MODES)[number])) {
      return raw;
    }
    return undefined;
  },
};

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: "exponential" | "linear";
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

type FieldParser = (raw: Record<string, string>) => Partial<RetryConfig>;

const FIELD_PARSERS: Record<keyof RetryConfig, FieldParser> = {
  maxAttempts(raw) {
    const n = parseNumber(raw.maxAttempts, 1, 10);
    return n !== null ? { maxAttempts: n } : {};
  },
  backoffMs(raw) {
    const n = parseNumber(raw.backoffMs, 0, Infinity);
    return n !== null ? { backoffMs: n } : {};
  },
  jitter(raw) {
    const v = parseBool(raw.jitter);
    return v !== null ? { jitter: v } : {};
  },
  mode(raw) {
    return VALID_MODES.has(raw.mode) ? { mode: raw.mode } : {};
  },
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const [key, fn] of Object.entries(FIELD_PARSERS)) {
    Object.assign(config, fn(raw));
  }

  return config;
}

function parseNumber(value: string, min: number, max: number): number | null {
  const n = Number(value);
  return Number.isInteger(n) && n >= min && n <= max ? n : null;
}

function parseBool(value: string): boolean | null {
  if (value === "true") return true;
