  jitter: true,
  mode: "exponential",
} as const;

const VALID_MODES = new Set(["exponential", "linear"]);

function parseIntegerInRange(value: string, min: number, max: number): number | null {
  const parsed = Number(value);
  if (Number.isInteger(parsed) && parsed >= min && parsed <= max) {
    return parsed;
  }
  return null;
}

function parseBooleanFlag(value: string): boolean | null {
  switch (value) {
    case "true":
      return true;
    case "false":
      return false;
    default:
      return null;
