}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = {
    maxAttempts: DEFAULT_RETRY_CONFIG.maxAttempts,
    backoffMs: DEFAULT_RETRY_CONFIG.backoffMs,
    jitter: DEFAULT_RETRY_CONFIG.jitter,
    mode: DEFAULT_RETRY_CONFIG.mode,
  };

  if (raw.maxAttempts !== undefined) {
    const parsed = parseIntegerInRange(raw.maxAttempts, 1, 10);
    if (parsed !== null) config.maxAttempts = parsed;
  }

  if (raw.backoffMs !== undefined) {
    const parsed = parseIntegerInRange(raw.backoffMs, 0, Infinity);
