  }

  if (raw.jitter !== undefined) {
    const parsed = parseBooleanFlag(raw.jitter);
    if (parsed !== null) config.jitter = parsed;
  }

  if (raw.mode !== undefined && VALID_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

function safeParseInt(value: string): number | null {
  const trimmed = value.trim();
  const parsed = Number(trimmed);
  return Number.isInteger(parsed) ? parsed : null;
}

function safeParseBool(value: string): boolean | null {
  const trimmed = value.trim().toLowerCase();
  if (trimmed === "true") return true;
  if (trimmed === "false") return false;
  return null;
}

const FIELD_RESOLVERS: Record<string, (raw: string) => unknown> = {
  maxAttempts(raw) {
    const v = safeParseInt(raw);
    return v != null && v >= 1 && v <= 10 ? v : undefined;
  },
  backoffMs(raw) {
    const v = safeParseInt(raw);
    return v != null && v >= 0 ? v : undefined;
  },
  jitter(raw) {
    return safeParseBool(raw) ?? undefined;
  },
  mode(raw) {
    const trimmed = raw.trim();
    return VALID_MODES.has(trimmed) ? trimmed : undefined;
  },
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  if (raw == null || typeof raw !== "object") {
    return { ...DEFAULT_RETRY_CONFIG };
  }

  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const [key, resolve] of Object.entries(FIELD_RESOLVERS)) {
    if (key in raw) {
      const value = resolve(raw[key]);
      if (value !== undefined) {
        (config as unknown as Record<string, unknown>)[key] = value;
      }
    }
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

type ConfigField = keyof RetryConfig;

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const validators: Record<ConfigField, (value: string) => boolean | null> = {
    maxAttempts: (value) => {
      const n = Number(value);
      return Number.isInteger(n) && n >= 1 && n <= 10 ? n : null;
    },
    backoffMs: (value) => {
      const n = Number(value);
      return Number.isInteger(n) && n >= 0 ? n : null;
    },
    jitter: (value) => {
      if (value === "true") return true;
      if (value === "false") return false;
      return null;
    },
    mode: (value) => (VALID_MODES.has(value) ? value : null),
  };

  for (const field of Object.keys(validators) as ConfigField[]) {
    const rawValue = raw[field];
    if (rawValue === undefined) continue;

    const result = validators[field](rawValue);
    if (result === null) continue;

    config[field] = result;
  }

  return config;
}

export interface RetryConfig {
  readonly maxAttempts: number;
  readonly backoffMs: number;
  readonly jitter: boolean;
  readonly mode: string;
}

const DEFAULT_RETRY_CONFIG: Required<RetryConfig> = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

function parseNumeric(
  raw: string | undefined,
  min: number,
  max: number
): number | null {
  if (raw === undefined) return null;

  const value = Number(raw);
  if (Number.isInteger(value) && value >= min && value <= max) {
    return value;
  }

  return null;
}

const BOOLEAN_MAP: Record<string, boolean> = {
  true: true,
  false: false,
};

const VALID_MODES: Record<string, string> = {
  exponential: "exponential",
  linear: "linear",
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseNumeric(raw.maxAttempts, 1, 10);
  if (maxAttempts !== null) config.maxAttempts = maxAttempts;

  const backoffMs = parseNumeric(raw.backoffMs, 0, Infinity);
  if (backoffMs !== null) config.backoffMs = backoffMs;

  const jitter = BOOLEAN_MAP[raw.jitter];
  if (jitter !== undefined) config.jitter = jitter;

  const mode = VALID_MODES[raw.mode];
  if (mode !== undefined) config.mode = mode;

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

function isNonEmptyString(value: string): boolean {
  return value.trim().length > 0;
}

const FIELD_PARSERS: {
  [K in keyof RetryConfig]?: (raw: Record<string, string>) => RetryConfig[K] | undefined;
} = {
  maxAttempts(raw) {
    if (!isNonEmptyString(raw.maxAttempts)) return undefined;
    const num = Number(raw.maxAttempts);
    return Number.isInteger(num) && num >= 1 && num <= 10 ? num : undefined;
  },
  backoffMs(raw) {
    if (!isNonEmptyString(raw.backoffMs)) return undefined;
    const num = Number(raw.backoffMs);
    return Number.isInteger(num) && num >= 0 ? num : undefined;
  },
  jitter(raw) {
    if (!isNonEmptyString(raw.jitter)) return undefined;
    if (raw.jitter === "true") return true;
    if (raw.jitter === "false") return false;
    return undefined;
  },
  mode(raw) {
    return raw.mode !== undefined && VALID_MODES.has(raw.mode) ? raw.mode : undefined;
  },
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };
  for (const [key, parse] of Object.entries(FIELD_PARSERS)) {
    const value = parse?.(raw);
    if (value !== undefined) (config as unknown as Record<string, unknown>)[key] = value;
  }
  return config;
}

