export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const BASE_PRICING: Record<ShipmentOrder["zone"], [number, number, number, number]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

function baseCost(zone: ShipmentOrder["zone"], weightKg: number): number {
  const tiers = BASE_PRICING[zone];
  if (weightKg <= 1) return tiers[0];
  if (weightKg <= 5) return tiers[1];
  if (weightKg <= 20) return tiers[2];
  return tiers[3];
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = baseCost(order.zone, order.weightKg);

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const WEIGHT_TIERS = [
  { maxKg: 1, domestic: 4, regional: 9, international: 18 },
  { maxKg: 5, domestic: 7, regional: 15, international: 30 },
  { maxKg: 20, domestic: 12, regional: 25, international: 55 },
] as const;

const HEAVY_TIER = { domestic: 20, regional: 40, international: 55 };
const PRIORITY_MULTIPLIER = 2;
const FRAGILE_SURCHARGE = 6;
const FRAGILE_WEIGHT_THRESHOLD_KG = 5;

export function shippingCost(order: ShipmentOrder): number {
  let base = findBaseCost(order.zone, order.weightKg);

  if (order.priority) {
    base *= PRIORITY_MULTIPLIER;
  }

  if (order.fragile && order.weightKg > FRAGILE_WEIGHT_THRESHOLD_KG) {
    base += FRAGILE_SURCHARGE;
  }

  return base;
}

function findBaseCost(
  zone: ShipmentOrder["zone"],
  weightKg: number,
): number {
  for (const tier of WEIGHT_TIERS) {
    if (weightKg <= tier.maxKg) {
      return tier[zone];
    }
  }

  return HEAVY_TIER[zone];
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const ZONE_INDEX: Record<ShipmentOrder["zone"], number> = {
  domestic: 0,
  regional: 1,
  international: 2,
};

const WEIGHT_THRESHOLDS = [1, 5, 20];

const BASE_COSTS: number[][] = [
  [4, 7, 12, 20],
  [9, 15, 25, 40],
  [18, 30, 55, 55],
];

export function shippingCost(order: ShipmentOrder): number {
  const zoneIndex = ZONE_INDEX[order.zone];
  const weightBracket = bracketIndex(order.weightKg);
  let base = BASE_COSTS[zoneIndex][weightBracket];

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

function bracketIndex(weightKg: number): number {
  let bracket = 0;
  for (let i = 0; i < WEIGHT_THRESHOLDS.length; i++) {
    if (weightKg <= WEIGHT_THRESHOLDS[i]) {
      bracket = i;
      break;
    }
    bracket = i + 1;
  }
  return bracket;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

export function shippingCost(order: ShipmentOrder): number {
  const weightBrackets: [number, number][] = [
    [1, getBase(order.zone, "under1")],
    [5, getBase(order.zone, "under5")],
    [20, getBase(order.zone, "under20")],
  ];

  let cost = getBase(order.zone, "default");
  for (const [limit, price] of weightBrackets) {
    if (order.weightKg <= limit) {
      cost = price;
      break;
    }
  }

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

const BRACKET_PRICES: Record<
  ShipmentOrder["zone"],
  Record<string, number>
> = {
  domestic: { under1: 4, under5: 7, under20: 12, default: 20 },
  regional: { under1: 9, under5: 15, under20: 25, default: 40 },
  international: { under1: 18, under5: 30, under20: 55, default: 55 },
};

function getBase(zone: ShipmentOrder["zone"], bracket: string): number {
  return BRACKET_PRICES[zone][bracket] ?? BRACKET_PRICES[zone].default;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const WEIGHT_BRACKETS = [1, 5, 20] as const;

const BASE_RATES: Record<ShipmentOrder["zone"], [number, number, number, number]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

function getBaseRate(zone: ShipmentOrder["zone"], weightKg: number): number {
  const rates = BASE_RATES[zone];
  for (let i = 0; i < WEIGHT_BRACKETS.length; i++) {
    if (weightKg <= WEIGHT_BRACKETS[i]) {
      return rates[i];
    }
  }
  return rates[3];
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = getBaseRate(order.zone, order.weightKg);

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const BASE_COSTS: Record<ShipmentOrder["zone"], number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55],
};

function weightIndex(weightKg: number): number {
  if (weightKg <= 1) return 0;
  if (weightKg <= 5) return 1;
  if (weightKg <= 20) return 2;
  return 3;
}

export function shippingCost(order: ShipmentOrder): number {
  const idx = Math.min(weightIndex(order.weightKg), BASE_COSTS[order.zone].length - 1);
  let base = BASE_COSTS[order.zone][idx];

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const BASE_COSTS: number[][] = [
  [4, 7, 12, 20],
  [9, 15, 25, 40],
  [18, 30, 55, 55],
];

const ZONE_INDEX: Record<ShipmentOrder["zone"], number> = {
  domestic: 0,
  regional: 1,
  international: 2,
};

function weightBracketIndex(weightKg: number): number {
  if (weightKg <= 1) return 0;
  if (weightKg <= 5) return 1;
  if (weightKg <= 20) return 2;
  return 3;
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = BASE_COSTS[ZONE_INDEX[order.zone]][weightBracketIndex(order.weightKg)];

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

export function shippingCost(order: ShipmentOrder): number {
  const base = zoneCost(order.zone, order.weightKg);

  let total = base;
  if (order.priority) {
    total *= 2;
  }
  if (order.fragile && order.weightKg > 5) {
    total += 6;
  }

  return total;
}

const ZONE_COSTS: Record<ShipmentOrder["zone"], readonly number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

function zoneCost(zone: ShipmentOrder["zone"], weightKg: number): number {
  const idx = weightIndex(weightKg);
  return ZONE_COSTS[zone][idx];
}

function weightIndex(weightKg: number): number {
  if (weightKg <= 1) return 0;
  if (weightKg <= 5) return 1;
  if (weightKg <= 20) return 2;
  return 3;
}

files.process_batch.ts:
export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const VALID_UNITS = new Set(["uV", "mV", "V"]);

const THRESHOLDS = {
  STANDBY_MAX: 50,
  IDLE_MAX: 200,
  ACTIVE_MAX: 600,
  LOADED_MAX: 900,
} as const;

const SEVERITY_ORDER: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
  unknown: 6,
};

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    parsed.push({
      channel: outcome.channel,
      millivolts: normalizeValue(outcome.unit, outcome.value),
      at: outcome.at,
    });
  }
  const labels = parsed.map((reading) => classifySignal(reading.millivolts));
  const alerts = collectAlerts(parsed, labels);
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(
    parsed.length,
    Object.keys(channels).length,
    alerts.length,
    labels
  );
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  const count = batch.readings.length;
  if (count === 0) {
    return "empty batch";
  }
  if (count > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return `reading ${index}: malformed`;
  }
  const record = entry as Record<string, unknown>;

  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return `reading ${index}: bad channel`;
  }
  if (!VALID_UNITS.has(record.unit as string)) {
    return `reading ${index}: bad unit`;
  }
  if (!Number.isInteger(record.value)) {
    return `reading ${index}: bad value`;
  }
  if (!isNonNegativeInt(record.at)) {
    return `reading ${index}: bad timestamp`;
  }

  return {
    channel: record.channel,
    unit: record.unit as string,
    value: record.value as number,
    at: record.at as number,
  };
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  switch (unit) {
    case "V":
      return value * 1000;
    case "uV":
      return Math.trunc(value / 1000);
    case "mV":
    default:
      return value;
  }
}

export function classifySignal(millivolts: number): string {
  if (millivolts < 0) {
    return "negative";
  }
  if (millivolts < THRESHOLDS.STANDBY_MAX) {
    return "standby";
  }
  if (millivolts < THRESHOLDS.IDLE_MAX) {
    return "idle";
  }
  if (millivolts < THRESHOLDS.ACTIVE_MAX) {
    return "active";
  }
  if (millivolts < THRESHOLDS.LOADED_MAX) {
    return "loaded";
  }
  return "critical";
}

function severityRank(label: string): number {
  return SEVERITY_ORDER[label] ?? SEVERITY_ORDER.unknown;
}

function collectAlerts(parsed: ParsedReading[], labels: string[]): string[] {
  const alerts: string[] = [];
  for (let index = 0; index < parsed.length; index++) {
    const reading = parsed[index];
    const label = labels[index];
    if (label === "critical") {
      alerts.push(`${reading.channel}:critical`);
    } else if (label === "negative") {
      alerts.push(`${reading.channel}:negative`);
    } else if (label === "loaded") {
      alerts.push(`${reading.channel}:loaded`);
    }
  }
  return alerts;
}

function channelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let index = 0; index < parsed.length; index++) {
    const reading = parsed[index];
    const label = labels[index];
    const existing = channels[reading.channel];
    if (existing === undefined) {
      channels[reading.channel] = {
        count: 1,
        min: reading.millivolts,
        max: reading.millivolts,
        worst: label,
      };
      continue;
    }
    existing.count++;
    if (reading.millivolts < existing.min) {
      existing.min = reading.millivolts;
    }
    if (reading.millivolts > existing.max) {
      existing.max = reading.millivolts;
    }
    if (severityRank(label) > severityRank(existing.worst)) {
      existing.worst = label;
    }
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  for (const label of labels) {
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }
  }
  return `readings=${readingCount};channels=${channelCount};alerts=${alertCount};worst=${worst}`;
}

export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const VALID_UNITS = new Set(["uV", "mV", "V"]);

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    parsed.push({ channel: outcome.channel, millivolts: normalizeValue(outcome.unit, outcome.value), at: outcome.at });
  }
  const labels = parsed.map((reading) => classifySignal(reading.millivolts));
  const alerts = collectAlerts(parsed);
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, labels);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  if (batch.readings.length === 0) {
    return "empty batch";
  }
  if (batch.readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function isValidUnit(unit: unknown): unit is string {
  return typeof unit === "string" && VALID_UNITS.has(unit);
}

function isNumericInt(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

function isNonNegativeInt(value: unknown): boolean {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

type FieldValidator = (record: Record<string, unknown>, index: number) => string | null;

const validators: Record<string, FieldValidator> = {
  channel: (record, index) => (typeof record.channel !== "string" || record.channel.length === 0)
    ? "reading " + index + ": bad channel" : null,
  unit: (record, index) => !isValidUnit(record.unit)
    ? "reading " + index + ": bad unit" : null,
  value: (record, index) => !isNumericInt(record.value)
    ? "reading " + index + ": bad value" : null,
  at: (record, index) => !isNonNegativeInt(record.at)
    ? "reading " + index + ": bad timestamp" : null,
};

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return "reading " + index + ": malformed";
  }
  const record = entry as Record<string, unknown>;
  for (const name of Object.keys(validators)) {
